-- Warrior voices: distinct cultures, attitudes, memories and emotes
local _, addon = ...
addon.localeData.enUS.racial = {
    GNOME = {
        HEROIC_STRIKE = { "A clean experiment calls for an accurate hit. Know why this blade is heavy? It rarely argues back.", "*adjusts an absurdly small protective visor; shifts weight onto the leading foot and brings the weapon down hard.*", "If it works, I shall publish the findings. Some arguments don't need a second sentence.", "*checks a loose fastener on the armour; drives the shoulder forward and lets the steel finish the point.*" },
        CHARGE = { "Velocity times mass! Don't check the numbers, I'm already moving!", "*checks a loose fastener on the armour; lowers a shoulder and launches forward in a cloud of dust.*", "Please don't touch anything I've just calibrated! Coming through! That's a direction, not a warning!", "*taps a bent measuring dial twice; bursts through an opening with a tremendous clatter.*" },
        REND = { "A clean experiment calls for an accurate hit. Armour seams are tiny secrets. I'm curious.", "*taps a bent measuring dial twice; draws the blade across an exposed gap in the guard.*", "Outsiders call it chaos. I call it data. A tailor would be horrified. I'm quite pleased.", "*hides a tiny tool in a glove; draws the blade back and searches for another opening.*" },
        HAMSTRING = { "A clean experiment calls for an accurate hit. Running away? That's a plan with serious flaws.", "*hides a tiny tool in a glove; ducks low beneath the enemy's guard.*", "A touch of insanity does not make the design defective. I dislike chasing twice. Once is plenty.", "*pulls the safety goggles into place; sweeps low with the weapon and rises into guard again.*" },
        THUNDER_CLAP = { "If the measuring needle snaps, the noise was sufficient.", "*pulls the safety goggles into place; stamps so hard that dust leaps from the earth.*", "If it works, I shall publish the findings. Hear that? Even the earth has objections.", "*scribbles a number onto the shield while moving; throws both arms wide as a dull boom rolls through the line.*" },
        CLEAVE = { "The simulation improves enormously with actual opponents. If you stand shoulder to shoulder, you can share the trouble.", "*scribbles a number onto the shield while moving; sends the weapon sweeping across a crowded arc.*", "Please don't touch anything I've just calibrated! I hope you left enough room. I didn't.", "*adjusts an absurdly small protective visor; pivots on one heel and carries the momentum into the next arc.*" },
        EXECUTE = { "A clean experiment calls for an accurate hit. I gave you every chance to withdraw.", "*adjusts an absurdly small protective visor; waits for a heartbeat, then brings down a final-looking blow.*", "Outsiders call it chaos. I call it data. Negotiations are over.", "*checks a loose fastener on the armour; tightens the grip and closes the last opening.*" },
        SUNDER_ARMOR = { "A clean experiment calls for an accurate hit. Lovely breastplate. Shame about the rivets.", "*checks a loose fastener on the armour; sets the blade against a loose edge of armour.*", "A touch of insanity does not make the design defective. Expensive steel isn't the same as good protection.", "*taps a bent measuring dial twice; traces a hard line along a gap between metal plates.*" },
        SHIELD_BLOCK = { "The warranty covers three ogres. After that we negotiate.", "*taps a bent measuring dial twice; turns the shield's rim to catch an incoming strike.*", "If it works, I shall publish the findings. A good shield listens before it answers.", "*hides a tiny tool in a glove; plants both boots and refuses to give an inch.*" },
        SHIELD_BASH = { "A clean experiment calls for an accurate hit. Hush. Let's see if I can interrupt your spell.", "*hides a tiny tool in a glove; drives the shield forward between two syllables.*", "Please don't touch anything I've just calibrated! My answer to magic comes with a wooden handle.", "*pulls the safety goggles into place; steps close and snaps the shield out without warning.*" },
        TAUNT = { "A clean experiment calls for an accurate hit. Over here! The trouble has my name on it.", "*pulls the safety goggles into place; rattles the sword hilt against the shield three times.*", "Outsiders call it chaos. I call it data. The others are busy. I'm not.", "*scribbles a number onto the shield while moving; steps out from the line and beckons the enemies closer.*" },
        BATTLE_SHOUT = { "The acoustic apparatus is ready for field testing. Heads up, ranks closed! No one falls alone today!", "*scribbles a number onto the shield while moving; beats the weapon hilt against the shield in rhythm.*", "A touch of insanity does not make the design defective. You've legs to stand on and hearts to endure. Use both!", "*adjusts an absurdly small protective visor; rises before the allies and lifts the blade high.*" },
        DEMORALIZING_SHOUT = { "The acoustic apparatus is ready for field testing. The first of you are shaking. The rest will notice soon!", "*adjusts an absurdly small protective visor; unleashes a rough, deep cry from the chest.*", "If it works, I shall publish the findings. Look around. Who are you still fighting for?", "*checks a loose fastener on the armour; points the blade at the wavering enemy line.*" },
        REVENGE = { "A clean experiment calls for an accurate hit. Thanks for the opportunity. It's coming right back.", "*checks a loose fastener on the armour; turns a weapon aside and strikes into the opening.*", "Please don't touch anything I've just calibrated! I forget faces. Never blows.", "*taps a bent measuring dial twice; rolls straight from defence into a counterattack.*" },
        OVERPOWER = { "A clean experiment calls for an accurate hit. There's a gap. How generous of you.", "*taps a bent measuring dial twice; slips past the missed strike and takes the open angle.*", "Outsiders call it chaos. I call it data. Miss me once, invite me in.", "*hides a tiny tool in a glove; turns an enemy misstep into a swift counter.*" },
        MORTAL_STRIKE = { "A clean experiment calls for an accurate hit. I'm not saving anything for a second try.", "*hides a tiny tool in a glove; sets both hands on the weapon and throws the body behind one strike.*", "A touch of insanity does not make the design defective. Some duels end with words. Not this one.", "*pulls the safety goggles into place; steps forward and guides the steel with merciless precision.*" },
        WHIRLWIND = { "The simulation improves enormously with actual opponents. Go on, stand in a circle. Makes things easier.", "*pulls the safety goggles into place; spins through the press of bodies with the weapon extended.*", "If it works, I shall publish the findings. I like sharing. Today it's steel.", "*scribbles a number onto the shield while moving; sends the blade singing around in a wide sweep.*" },
        BLOODTHIRST = { "A controlled overload is not a malfunction. The pulse is racing. The hand stays steady.", "*scribbles a number onto the shield while moving; draws a sharp breath and presses the attack without mercy.*", "Please don't touch anything I've just calibrated! Anger doesn't mean I'm inaccurate.", "*adjusts an absurdly small protective visor; surges forward with wild eyes and a measured grip.*" },
        INTERCEPT = { "The acceleration was calculated beforehand, of course. A head start is borrowed time.", "*adjusts an absurdly small protective visor; bursts from the melee and cuts off the escape.*", "Outsiders call it chaos. I call it data. You're running? Excellent. I needed the exercise.", "*checks a loose fastener on the armour; springs off the ground and lands across the fleeing path.*" },
        PUMMEL = { "A clean experiment calls for an accurate hit. Too many words. Not enough guard.", "*checks a loose fastener on the armour; disrupts the casting motion with a sharp, precise strike.*", "A touch of insanity does not make the design defective. Were you saying something? No? Good.", "*taps a bent measuring dial twice; knocks an arm out of rhythm with a compact blow.*" },
        SWEEPING_STRIKES = { "The simulation improves enormously with actual opponents. Why do half the job when there's a whole battle?", "*taps a bent measuring dial twice; carries one swing smoothly into a second arc.*", "If it works, I shall publish the findings. More enemies? Fewer trips.", "*hides a tiny tool in a glove; keeps the blade moving through the crush instead of withdrawing it.*" },
        DEATH_WISH = { "A controlled overload is not a malfunction. Reason made its case. I disagreed.", "*hides a tiny tool in a glove; loosens the grip for a moment, then commits to the attack.*", "Please don't touch anything I've just calibrated! I know the risk. Not sure they do.", "*pulls the safety goggles into place; glances once at the lowered guard before lunging forward.*" },
        RECKLESSNESS = { "A controlled overload is not a malfunction. Caution was yesterday. Today we act.", "*pulls the safety goggles into place; casts hesitation aside without loosening the weapon grip.*", "Outsiders call it chaos. I call it data. You can lecture me tomorrow. If we have one.", "*scribbles a number onto the shield while moving; throws the whole body into a furious chain of strikes.*" },
        LAST_STAND = { "My safety precautions are finally proving useful. This far. Not one step further.", "*scribbles a number onto the shield while moving; hauls upright once more and lifts the shield.*", "A touch of insanity does not make the design defective. Still standing. That should answer you.", "*adjusts an absurdly small protective visor; sets shaking legs into the breach again.*" },
        SHIELD_WALL = { "My safety precautions are finally proving useful. Behind me! No private heroics!", "*adjusts an absurdly small protective visor; locks the shield close and braces into the allied line.*", "If it works, I shall publish the findings. Anyone going through me will need patience.", "*checks a loose fastener on the armour; closes the final gap between shield and armour.*" },
        RETALIATION = { "A clean experiment calls for an accurate hit. If you strike, you should enjoy the echo.", "*checks a loose fastener on the armour; leaves a narrow gap in the guard and answers each attack with steel.*", "Please don't touch anything I've just calibrated! Come on then. I have a moment for each of you.", "*taps a bent measuring dial twice; plants the feet and waits for the first impatient blows.*" },
        MOCKING_BLOW = { "A clean experiment calls for an accurate hit. Are you dangerous or merely loud?", "*taps a bent measuring dial twice; lets the weapon point hang too low and invites the foe closer.*", "Outsiders call it chaos. I call it data. Sorry. Mistook you for a training dummy.", "*hides a tiny tool in a glove; makes a cheeky swing and grins over the shield.*" },
        BERSERKER_RAGE = { "A controlled overload is not a malfunction. Fear? It has no room in my head today.", "*hides a tiny tool in a glove; rolls the shoulders as if shaking off an invisible weight.*", "A touch of insanity does not make the design defective. Fear can wait outside. Fury's coming in.", "*pulls the safety goggles into place; blows out a hard breath and holds an unbroken stare.*" },
        BLOODRAGE = { "A controlled overload is not a malfunction. Pain is a message. I'll answer later.", "*pulls the safety goggles into place; strikes a fist against the chest and gathers fighting spirit.*", "If it works, I shall publish the findings. My heart's still beating. That's enough explanation.", "*scribbles a number onto the shield while moving; grits the teeth and tightens the shoulders beneath the armour.*" },
        DISARM = { "A clean experiment calls for an accurate hit. Beautiful sword. May I see it a moment?", "*scribbles a number onto the shield while moving; tries to turn the enemy blade free with a short twist.*", "Please don't touch anything I've just calibrated! Let's see if you're as talkative without a weapon.", "*adjusts an absurdly small protective visor; tries to catch the weapon's grip and twist it out of line.*" },
        INTIMIDATING_SHOUT = { "The acoustic apparatus is ready for field testing. Run while you still remember the way!", "*adjusts an absurdly small protective visor; throws a savage roar over the heads of the enemy.*", "Outsiders call it chaos. I call it data. That was the friendly warning. The next comes with steel.", "*checks a loose fastener on the armour; crashes the hilt against the shield and bares the teeth.*" },
        CHALLENGING_SHOUT = { "The acoustic apparatus is ready for field testing. ALL OF YOU, TO ME! I've room for every grudge!", "*checks a loose fastener on the armour; throws both arms wide and challenges the entire enemy line.*", "A touch of insanity does not make the design defective. Leave the others! I'm your problem today!", "*taps a bent measuring dial twice; hammers the shield and bellows at the approaching foes.*" },
        SLAM = { "A clean experiment calls for an accurate hit. It's not a hammer. Won't feel much different, though.", "*taps a bent measuring dial twice; raises the weapon overhead and drops it with full weight.*", "If it works, I shall publish the findings. One clean hit beats five half-hearted ones.", "*hides a tiny tool in a glove; pauses for a heartbeat and lets the weapon crash down.*" },
        DEVASTATE = { "A clean experiment calls for an accurate hit. Already loose? Let's finish the job.", "*hides a tiny tool in a glove; strikes an already weakened patch of armour.*", "Please don't touch anything I've just calibrated! Looks like your smith saved money in the wrong place.", "*pulls the safety goggles into place; taps the exposed seam, then strikes again.*" },
        SHIELD_SLAM = { "A clean experiment calls for an accurate hit. Shields can close doors. Usually at face level.", "*pulls the safety goggles into place; rips the shield from its guard and thrusts the rim forward.*", "Outsiders call it chaos. I call it data. Whoever said defence was polite?", "*scribbles a number onto the shield while moving; lunges one step and lets the shield do the talking.*" },
        CONCUSSION_BLOW = { "A clean experiment calls for an accurate hit. I'll try to throw you off your stride.", "*scribbles a number onto the shield while moving; tries to land a heavy blow in the gap between two movements.*", "A touch of insanity does not make the design defective. I'll try to give everyone a moment of silence.", "*adjusts an absurdly small protective visor; shortens the grip and swings with startling force.*" },
        VICTORY_RUSH = { "The acceleration was calculated beforehand, of course. One down. The others are still standing.", "*adjusts an absurdly small protective visor; uses the sudden breath of victory to surge forward.*", "If it works, I shall publish the findings. We can celebrate later. Something's still moving.", "*checks a loose fastener on the armour; taps the chest once and presses on.*" },
        BATTLE_STANCE = { "The simulation improves enormously with actual opponents. Two feet of good sense separate courage from stupidity.", "*checks a loose fastener on the armour; plants both feet shoulder-width apart and rolls the blade loosely.*", "Please don't touch anything I've just calibrated! I'll stay ready. The rest can make up its mind.", "*taps a bent measuring dial twice; balances the weight between shield arm and sword hand.*" },
        DEFENSIVE_STANCE = { "My safety precautions are finally proving useful. If they want my friends, they must convince my shield.", "*taps a bent measuring dial twice; widens the stance and lifts the shield before the allies.*", "Outsiders call it chaos. I call it data. The loudest roar won't win this one.", "*hides a tiny tool in a glove; drops the centre of gravity and becomes a wall behind the guard.*" },
        BERSERKER_STANCE = { "A controlled overload is not a malfunction. Whoever said anger makes you blind has never looked properly.", "*hides a tiny tool in a glove; draws deep breath and assumes a fierce, forward stance.*", "A touch of insanity does not make the design defective. The world has become very simple: forward.", "*pulls the safety goggles into place; loosens the shoulders, lowers the weapon, then snaps it up.*" },
        PIERCING_HOWL = { "The acoustic apparatus is ready for field testing. If you hear me, you're already too close.", "*pulls the safety goggles into place; lets loose a howl that cuts through the surrounding clamour.*", "If it works, I shall publish the findings. No, that wasn't a pack of wolves. Just me.", "*scribbles a number onto the shield while moving; throws the head back and sustains a long, harsh cry.*" },
        SPEARING_STRIKE = { "A clean experiment calls for an accurate hit. The opening is narrow. My point isn't.", "*scribbles a number onto the shield while moving; steps directly forward with the weapon extended.*", "Please don't touch anything I've just calibrated! Armour is strong. Angles are stronger.", "*adjusts an absurdly small protective visor; turns the wrist toward a weak spot and drives the point home.*" },
        TACTICAL_MASTERY = { "That's called problem solving under unfavourable experimental conditions.", "*adjusts an absurdly small protective visor; shifts position barely an inch and keeps the battlefield in view.*", "Outsiders call it chaos. I call it data. A battlefield isn't a dice game. You learn to read it.", "*checks a loose fastener on the armour; studies every path, foe and retreat without lowering the weapon.*" },
    },
    HUMAN = {
        HEROIC_STRIKE = { "The training was hard. Now it pays off. Know why this blade is heavy? It rarely argues back.", "*straightens the battered crest on the shield; shifts weight onto the leading foot and brings the weapon down hard.*", "The others depend on me. I won't fail them. Some arguments don't need a second sentence.", "*checks the allied formation with a quick glance; drives the shoulder forward and lets the steel finish the point.*" },
        CHARGE = { "Orders are useful. Leading from the front is better. If the road is blocked, I take the direct route.", "*checks the allied formation with a quick glance; lowers a shoulder and launches forward in a cloud of dust.*", "Keep your bearing, even when no one is watching. Coming through! That's a direction, not a warning!", "*tightens a leather strap around the forearm; bursts through an opening with a tremendous clatter.*" },
        REND = { "The training was hard. Now it pays off. Armour seams are tiny secrets. I'm curious.", "*tightens a leather strap around the forearm; draws the blade across an exposed gap in the guard.*", "A battle plan survives longer when someone defends it. A tailor would be horrified. I'm quite pleased.", "*gives a comrade a brief nod; draws the blade back and searches for another opening.*" },
        HAMSTRING = { "The training was hard. Now it pays off. Running away? That's a plan with serious flaws.", "*gives a comrade a brief nod; ducks low beneath the enemy's guard.*", "Under this armour there's still a promise. I dislike chasing twice. Once is plenty.", "*sets the helmet straight with a practiced motion; sweeps low with the weapon and rises into guard again.*" },
        THUNDER_CLAP = { "The training was hard. Now it pays off. When the ground shakes, who needs a drummer?", "*sets the helmet straight with a practiced motion; stamps so hard that dust leaps from the earth.*", "The others depend on me. I won't fail them. Hear that? Even the earth has objections.", "*runs a thumb over an old nick in the sword hilt; throws both arms wide as a dull boom rolls through the line.*" },
        CLEAVE = { "Read the terrain before giving the order to advance. If you stand shoulder to shoulder, you can share the trouble.", "*runs a thumb over an old nick in the sword hilt; sends the weapon sweeping across a crowded arc.*", "Keep your bearing, even when no one is watching. I hope you left enough room. I didn't.", "*straightens the battered crest on the shield; pivots on one heel and carries the momentum into the next arc.*" },
        EXECUTE = { "The training was hard. Now it pays off. I gave you every chance to withdraw.", "*straightens the battered crest on the shield; waits for a heartbeat, then brings down a final-looking blow.*", "A battle plan survives longer when someone defends it. Negotiations are over.", "*checks the allied formation with a quick glance; tightens the grip and closes the last opening.*" },
        SUNDER_ARMOR = { "The training was hard. Now it pays off. Lovely breastplate. Shame about the rivets.", "*checks the allied formation with a quick glance; sets the blade against a loose edge of armour.*", "Under this armour there's still a promise. Expensive steel isn't the same as good protection.", "*tightens a leather strap around the forearm; traces a hard line along a gap between metal plates.*" },
        SHIELD_BLOCK = { "The line is ours as long as we stand together. You'll have to knock first. This door stays closed.", "*tightens a leather strap around the forearm; turns the shield's rim to catch an incoming strike.*", "The others depend on me. I won't fail them. A good shield listens before it answers.", "*gives a comrade a brief nod; plants both boots and refuses to give an inch.*" },
        SHIELD_BASH = { "The training was hard. Now it pays off. Hush. Let's see if I can interrupt your spell.", "*gives a comrade a brief nod; drives the shield forward between two syllables.*", "Keep your bearing, even when no one is watching. My answer to magic comes with a wooden handle.", "*sets the helmet straight with a practiced motion; steps close and snaps the shield out without warning.*" },
        TAUNT = { "These people are under my protection. That isn't up for discussion.", "*sets the helmet straight with a practiced motion; rattles the sword hilt against the shield three times.*", "A battle plan survives longer when someone defends it. The others are busy. I'm not.", "*runs a thumb over an old nick in the sword hilt; steps out from the line and beckons the enemies closer.*" },
        BATTLE_SHOUT = { "Today we march for each other, not for a banner!", "*runs a thumb over an old nick in the sword hilt; beats the weapon hilt against the shield in rhythm.*", "Under this armour there's still a promise. You've legs to stand on and hearts to endure. Use both!", "*straightens the battered crest on the shield; rises before the allies and lifts the blade high.*" },
        DEMORALIZING_SHOUT = { "Sometimes one voice must stand in for an entire banner. The first of you are shaking. The rest will notice soon!", "*straightens the battered crest on the shield; unleashes a rough, deep cry from the chest.*", "The others depend on me. I won't fail them. Look around. Who are you still fighting for?", "*checks the allied formation with a quick glance; points the blade at the wavering enemy line.*" },
        REVENGE = { "In my training, they called that a lesson.", "*checks the allied formation with a quick glance; turns a weapon aside and strikes into the opening.*", "Keep your bearing, even when no one is watching. I forget faces. Never blows.", "*tightens a leather strap around the forearm; rolls straight from defence into a counterattack.*" },
        OVERPOWER = { "The training was hard. Now it pays off. There's a gap. How generous of you.", "*tightens a leather strap around the forearm; slips past the missed strike and takes the open angle.*", "A battle plan survives longer when someone defends it. Miss me once, invite me in.", "*gives a comrade a brief nod; turns an enemy misstep into a swift counter.*" },
        MORTAL_STRIKE = { "The training was hard. Now it pays off. I'm not saving anything for a second try.", "*gives a comrade a brief nod; sets both hands on the weapon and throws the body behind one strike.*", "Under this armour there's still a promise. Some duels end with words. Not this one.", "*sets the helmet straight with a practiced motion; steps forward and guides the steel with merciless precision.*" },
        WHIRLWIND = { "Read the terrain before giving the order to advance. Go on, stand in a circle. Makes things easier.", "*sets the helmet straight with a practiced motion; spins through the press of bodies with the weapon extended.*", "The others depend on me. I won't fail them. I like sharing. Today it's steel.", "*runs a thumb over an old nick in the sword hilt; sends the blade singing around in a wide sweep.*" },
        BLOODTHIRST = { "Anger without discipline strikes the wrong people. The pulse is racing. The hand stays steady.", "*runs a thumb over an old nick in the sword hilt; draws a sharp breath and presses the attack without mercy.*", "Keep your bearing, even when no one is watching. Anger doesn't mean I'm inaccurate.", "*straightens the battered crest on the shield; surges forward with wild eyes and a measured grip.*" },
        INTERCEPT = { "Orders are useful. Leading from the front is better. A head start is borrowed time.", "*straightens the battered crest on the shield; bursts from the melee and cuts off the escape.*", "A battle plan survives longer when someone defends it. You're running? Excellent. I needed the exercise.", "*checks the allied formation with a quick glance; springs off the ground and lands across the fleeing path.*" },
        PUMMEL = { "The training was hard. Now it pays off. Too many words. Not enough guard.", "*checks the allied formation with a quick glance; disrupts the casting motion with a sharp, precise strike.*", "Under this armour there's still a promise. Were you saying something? No? Good.", "*tightens a leather strap around the forearm; knocks an arm out of rhythm with a compact blow.*" },
        SWEEPING_STRIKES = { "Read the terrain before giving the order to advance. Why do half the job when there's a whole battle?", "*tightens a leather strap around the forearm; carries one swing smoothly into a second arc.*", "The others depend on me. I won't fail them. More enemies? Fewer trips.", "*gives a comrade a brief nod; keeps the blade moving through the crush instead of withdrawing it.*" },
        DEATH_WISH = { "Anger without discipline strikes the wrong people. Reason made its case. I disagreed.", "*gives a comrade a brief nod; loosens the grip for a moment, then commits to the attack.*", "Keep your bearing, even when no one is watching. I know the risk. Not sure they do.", "*sets the helmet straight with a practiced motion; glances once at the lowered guard before lunging forward.*" },
        RECKLESSNESS = { "Anger without discipline strikes the wrong people. Caution was yesterday. Today we act.", "*sets the helmet straight with a practiced motion; casts hesitation aside without loosening the weapon grip.*", "A battle plan survives longer when someone defends it. You can lecture me tomorrow. If we have one.", "*runs a thumb over an old nick in the sword hilt; throws the whole body into a furious chain of strikes.*" },
        LAST_STAND = { "A line is only lost when the last one defending it gives up.", "*runs a thumb over an old nick in the sword hilt; hauls upright once more and lifts the shield.*", "Under this armour there's still a promise. Still standing. That should answer you.", "*straightens the battered crest on the shield; sets shaking legs into the breach again.*" },
        SHIELD_WALL = { "The line is ours as long as we stand together. Behind me! No private heroics!", "*straightens the battered crest on the shield; locks the shield close and braces into the allied line.*", "The others depend on me. I won't fail them. Anyone going through me will need patience.", "*checks the allied formation with a quick glance; closes the final gap between shield and armour.*" },
        RETALIATION = { "The training was hard. Now it pays off. If you strike, you should enjoy the echo.", "*checks the allied formation with a quick glance; leaves a narrow gap in the guard and answers each attack with steel.*", "Keep your bearing, even when no one is watching. Come on then. I have a moment for each of you.", "*tightens a leather strap around the forearm; plants the feet and waits for the first impatient blows.*" },
        MOCKING_BLOW = { "The training was hard. Now it pays off. Are you dangerous or merely loud?", "*tightens a leather strap around the forearm; lets the weapon point hang too low and invites the foe closer.*", "A battle plan survives longer when someone defends it. Sorry. Mistook you for a training dummy.", "*gives a comrade a brief nod; makes a cheeky swing and grins over the shield.*" },
        BERSERKER_RAGE = { "Anger without discipline strikes the wrong people. Fear? It has no room in my head today.", "*gives a comrade a brief nod; rolls the shoulders as if shaking off an invisible weight.*", "Under this armour there's still a promise. Fear can wait outside. Fury's coming in.", "*sets the helmet straight with a practiced motion; blows out a hard breath and holds an unbroken stare.*" },
        BLOODRAGE = { "Anger without discipline strikes the wrong people. Pain is a message. I'll answer later.", "*sets the helmet straight with a practiced motion; strikes a fist against the chest and gathers fighting spirit.*", "The others depend on me. I won't fail them. My heart's still beating. That's enough explanation.", "*runs a thumb over an old nick in the sword hilt; grits the teeth and tightens the shoulders beneath the armour.*" },
        DISARM = { "The training was hard. Now it pays off. Beautiful sword. May I see it a moment?", "*runs a thumb over an old nick in the sword hilt; tries to turn the enemy blade free with a short twist.*", "Keep your bearing, even when no one is watching. Let's see if you're as talkative without a weapon.", "*straightens the battered crest on the shield; tries to catch the weapon's grip and twist it out of line.*" },
        INTIMIDATING_SHOUT = { "Sometimes one voice must stand in for an entire banner. Run while you still remember the way!", "*straightens the battered crest on the shield; throws a savage roar over the heads of the enemy.*", "A battle plan survives longer when someone defends it. That was the friendly warning. The next comes with steel.", "*checks the allied formation with a quick glance; crashes the hilt against the shield and bares the teeth.*" },
        CHALLENGING_SHOUT = { "Sometimes one voice must stand in for an entire banner. ALL OF YOU, TO ME! I've room for every grudge!", "*checks the allied formation with a quick glance; throws both arms wide and challenges the entire enemy line.*", "Under this armour there's still a promise. Leave the others! I'm your problem today!", "*tightens a leather strap around the forearm; hammers the shield and bellows at the approaching foes.*" },
        SLAM = { "The training was hard. Now it pays off. It's not a hammer. Won't feel much different, though.", "*tightens a leather strap around the forearm; raises the weapon overhead and drops it with full weight.*", "The others depend on me. I won't fail them. One clean hit beats five half-hearted ones.", "*gives a comrade a brief nod; pauses for a heartbeat and lets the weapon crash down.*" },
        DEVASTATE = { "The training was hard. Now it pays off. Already loose? Let's finish the job.", "*gives a comrade a brief nod; strikes an already weakened patch of armour.*", "Keep your bearing, even when no one is watching. Looks like your smith saved money in the wrong place.", "*sets the helmet straight with a practiced motion; taps the exposed seam, then strikes again.*" },
        SHIELD_SLAM = { "The training was hard. Now it pays off. Shields can close doors. Usually at face level.", "*sets the helmet straight with a practiced motion; rips the shield from its guard and thrusts the rim forward.*", "A battle plan survives longer when someone defends it. Whoever said defence was polite?", "*runs a thumb over an old nick in the sword hilt; lunges one step and lets the shield do the talking.*" },
        CONCUSSION_BLOW = { "The training was hard. Now it pays off. I'll try to throw you off your stride.", "*runs a thumb over an old nick in the sword hilt; tries to land a heavy blow in the gap between two movements.*", "Under this armour there's still a promise. I'll try to give everyone a moment of silence.", "*straightens the battered crest on the shield; shortens the grip and swings with startling force.*" },
        VICTORY_RUSH = { "Orders are useful. Leading from the front is better. One down. The others are still standing.", "*straightens the battered crest on the shield; uses the sudden breath of victory to surge forward.*", "The others depend on me. I won't fail them. We can celebrate later. Something's still moving.", "*checks the allied formation with a quick glance; taps the chest once and presses on.*" },
        BATTLE_STANCE = { "Read the terrain before giving the order to advance. Two feet of good sense separate courage from stupidity.", "*checks the allied formation with a quick glance; plants both feet shoulder-width apart and rolls the blade loosely.*", "Keep your bearing, even when no one is watching. I'll stay ready. The rest can make up its mind.", "*tightens a leather strap around the forearm; balances the weight between shield arm and sword hand.*" },
        DEFENSIVE_STANCE = { "The line is ours as long as we stand together. If they want my friends, they must convince my shield.", "*tightens a leather strap around the forearm; widens the stance and lifts the shield before the allies.*", "A battle plan survives longer when someone defends it. The loudest roar won't win this one.", "*gives a comrade a brief nod; drops the centre of gravity and becomes a wall behind the guard.*" },
        BERSERKER_STANCE = { "Anger without discipline strikes the wrong people. Whoever said anger makes you blind has never looked properly.", "*gives a comrade a brief nod; draws deep breath and assumes a fierce, forward stance.*", "Under this armour there's still a promise. The world has become very simple: forward.", "*sets the helmet straight with a practiced motion; loosens the shoulders, lowers the weapon, then snaps it up.*" },
        PIERCING_HOWL = { "Sometimes one voice must stand in for an entire banner. If you hear me, you're already too close.", "*sets the helmet straight with a practiced motion; lets loose a howl that cuts through the surrounding clamour.*", "The others depend on me. I won't fail them. No, that wasn't a pack of wolves. Just me.", "*runs a thumb over an old nick in the sword hilt; throws the head back and sustains a long, harsh cry.*" },
        SPEARING_STRIKE = { "The training was hard. Now it pays off. The opening is narrow. My point isn't.", "*runs a thumb over an old nick in the sword hilt; steps directly forward with the weapon extended.*", "Keep your bearing, even when no one is watching. Armour is strong. Angles are stronger.", "*straightens the battered crest on the shield; turns the wrist toward a weak spot and drives the point home.*" },
        TACTICAL_MASTERY = { "Read the terrain before giving the order to advance. The difference between courage and foolishness is good footwork.", "*straightens the battered crest on the shield; shifts position barely an inch and keeps the battlefield in view.*", "A battle plan survives longer when someone defends it. A battlefield isn't a dice game. You learn to read it.", "*checks the allied formation with a quick glance; studies every path, foe and retreat without lowering the weapon.*" },
    },
    DWARF = {
        HEROIC_STRIKE = { "By my grandmother's beard, now that's honest work! Know why this blade is heavy? It rarely argues back.", "*rattles a knuckle against the dented shield rim; shifts weight onto the leading foot and brings the weapon down hard.*", "We'll talk about it over a pint later. Perhaps. Some arguments don't need a second sentence.", "*spits decisively into gloved hands; drives the shoulder forward and lets the steel finish the point.*" },
        CHARGE = { "These boots know only one direction: forward. If the road is blocked, I take the direct route.", "*spits decisively into gloved hands; lowers a shoulder and launches forward in a cloud of dust.*", "An anvil never complains when you strike it properly. Coming through! That's a direction, not a warning!", "*pulls the helm low over bushy brows; bursts through an opening with a tremendous clatter.*" },
        REND = { "By my grandmother's beard, now that's honest work! Armour seams are tiny secrets. I'm curious.", "*pulls the helm low over bushy brows; draws the blade across an exposed gap in the guard.*", "Shaking knees? Not in this family. A tailor would be horrified. I'm quite pleased.", "*plants the boots as though bracing against a mountain slope; draws the blade back and searches for another opening.*" },
        HAMSTRING = { "By my grandmother's beard, now that's honest work! Running away? That's a plan with serious flaws.", "*plants the boots as though bracing against a mountain slope; ducks low beneath the enemy's guard.*", "The stone remembers everyone who gave way before it. I dislike chasing twice. Once is plenty.", "*sweeps a stray strand of beard out of the way; sweeps low with the weapon and rises into guard again.*" },
        THUNDER_CLAP = { "By my grandmother's beard, now that's honest work! When the ground shakes, who needs a drummer?", "*sweeps a stray strand of beard out of the way; stamps so hard that dust leaps from the earth.*", "We'll talk about it over a pint later. Perhaps. Hear that? Even the earth has objections.", "*strikes the weapon pommel against the breastplate; throws both arms wide as a dull boom rolls through the line.*" },
        CLEAVE = { "My grandfather called that sound mountain sense. If you stand shoulder to shoulder, you can share the trouble.", "*strikes the weapon pommel against the breastplate; sends the weapon sweeping across a crowded arc.*", "An anvil never complains when you strike it properly. I hope you left enough room. I didn't.", "*rattles a knuckle against the dented shield rim; pivots on one heel and carries the momentum into the next arc.*" },
        EXECUTE = { "By my grandmother's beard, now that's honest work! I gave you every chance to withdraw.", "*rattles a knuckle against the dented shield rim; waits for a heartbeat, then brings down a final-looking blow.*", "Shaking knees? Not in this family. Negotiations are over.", "*spits decisively into gloved hands; tightens the grip and closes the last opening.*" },
        SUNDER_ARMOR = { "By my grandmother's beard, now that's honest work! Lovely breastplate. Shame about the rivets.", "*spits decisively into gloved hands; sets the blade against a loose edge of armour.*", "The stone remembers everyone who gave way before it. Expensive steel isn't the same as good protection.", "*pulls the helm low over bushy brows; traces a hard line along a gap between metal plates.*" },
        SHIELD_BLOCK = { "A mountain does not ask how strong the storm is. You'll have to knock first. This door stays closed.", "*pulls the helm low over bushy brows; turns the shield's rim to catch an incoming strike.*", "We'll talk about it over a pint later. Perhaps. A good shield listens before it answers.", "*plants the boots as though bracing against a mountain slope; plants both boots and refuses to give an inch.*" },
        SHIELD_BASH = { "By my grandmother's beard, now that's honest work! Hush. Let's see if I can interrupt your spell.", "*plants the boots as though bracing against a mountain slope; drives the shield forward between two syllables.*", "An anvil never complains when you strike it properly. My answer to magic comes with a wooden handle.", "*sweeps a stray strand of beard out of the way; steps close and snaps the shield out without warning.*" },
        TAUNT = { "By my grandmother's beard, now that's honest work! Over here! The trouble has my name on it.", "*sweeps a stray strand of beard out of the way; rattles the sword hilt against the shield three times.*", "Shaking knees? Not in this family. The others are busy. I'm not.", "*strikes the weapon pommel against the breastplate; steps out from the line and beckons the enemies closer.*" },
        BATTLE_SHOUT = { "Whoever's still standing gets my last cask of ale. Well, almost.", "*strikes the weapon pommel against the breastplate; beats the weapon hilt against the shield in rhythm.*", "The stone remembers everyone who gave way before it. You've legs to stand on and hearts to endure. Use both!", "*rattles a knuckle against the dented shield rim; rises before the allies and lifts the blade high.*" },
        DEMORALIZING_SHOUT = { "Anyone who can't hear that in the tavern is beyond help! The first of you are shaking. The rest will notice soon!", "*rattles a knuckle against the dented shield rim; unleashes a rough, deep cry from the chest.*", "We'll talk about it over a pint later. Perhaps. Look around. Who are you still fighting for?", "*spits decisively into gloved hands; points the blade at the wavering enemy line.*" },
        REVENGE = { "By my grandmother's beard, now that's honest work! Thanks for the opportunity. It's coming right back.", "*spits decisively into gloved hands; turns a weapon aside and strikes into the opening.*", "An anvil never complains when you strike it properly. I forget faces. Never blows.", "*pulls the helm low over bushy brows; rolls straight from defence into a counterattack.*" },
        OVERPOWER = { "By my grandmother's beard, now that's honest work! There's a gap. How generous of you.", "*pulls the helm low over bushy brows; slips past the missed strike and takes the open angle.*", "Shaking knees? Not in this family. Miss me once, invite me in.", "*plants the boots as though bracing against a mountain slope; turns an enemy misstep into a swift counter.*" },
        MORTAL_STRIKE = { "By my grandmother's beard, now that's honest work! I'm not saving anything for a second try.", "*plants the boots as though bracing against a mountain slope; sets both hands on the weapon and throws the body behind one strike.*", "The stone remembers everyone who gave way before it. Some duels end with words. Not this one.", "*sweeps a stray strand of beard out of the way; steps forward and guides the steel with merciless precision.*" },
        WHIRLWIND = { "My grandfather called that sound mountain sense. Go on, stand in a circle. Makes things easier.", "*sweeps a stray strand of beard out of the way; spins through the press of bodies with the weapon extended.*", "We'll talk about it over a pint later. Perhaps. I like sharing. Today it's steel.", "*strikes the weapon pommel against the breastplate; sends the blade singing around in a wide sweep.*" },
        BLOODTHIRST = { "My temper runs deep, right about ale-cask height. The pulse is racing. The hand stays steady.", "*strikes the weapon pommel against the breastplate; draws a sharp breath and presses the attack without mercy.*", "An anvil never complains when you strike it properly. Anger doesn't mean I'm inaccurate.", "*rattles a knuckle against the dented shield rim; surges forward with wild eyes and a measured grip.*" },
        INTERCEPT = { "These boots know only one direction: forward. A head start is borrowed time.", "*rattles a knuckle against the dented shield rim; bursts from the melee and cuts off the escape.*", "Shaking knees? Not in this family. You're running? Excellent. I needed the exercise.", "*spits decisively into gloved hands; springs off the ground and lands across the fleeing path.*" },
        PUMMEL = { "By my grandmother's beard, now that's honest work! Too many words. Not enough guard.", "*spits decisively into gloved hands; disrupts the casting motion with a sharp, precise strike.*", "The stone remembers everyone who gave way before it. Were you saying something? No? Good.", "*pulls the helm low over bushy brows; knocks an arm out of rhythm with a compact blow.*" },
        SWEEPING_STRIKES = { "My grandfather called that sound mountain sense. Why do half the job when there's a whole battle?", "*pulls the helm low over bushy brows; carries one swing smoothly into a second arc.*", "We'll talk about it over a pint later. Perhaps. More enemies? Fewer trips.", "*plants the boots as though bracing against a mountain slope; keeps the blade moving through the crush instead of withdrawing it.*" },
        DEATH_WISH = { "My temper runs deep, right about ale-cask height. Reason made its case. I disagreed.", "*plants the boots as though bracing against a mountain slope; loosens the grip for a moment, then commits to the attack.*", "An anvil never complains when you strike it properly. I know the risk. Not sure they do.", "*sweeps a stray strand of beard out of the way; glances once at the lowered guard before lunging forward.*" },
        RECKLESSNESS = { "My temper runs deep, right about ale-cask height. Caution was yesterday. Today we act.", "*sweeps a stray strand of beard out of the way; casts hesitation aside without loosening the weapon grip.*", "Shaking knees? Not in this family. You can lecture me tomorrow. If we have one.", "*strikes the weapon pommel against the breastplate; throws the whole body into a furious chain of strikes.*" },
        LAST_STAND = { "A mountain does not ask how strong the storm is. This far. Not one step further.", "*strikes the weapon pommel against the breastplate; hauls upright once more and lifts the shield.*", "The stone remembers everyone who gave way before it. Still standing. That should answer you.", "*rattles a knuckle against the dented shield rim; sets shaking legs into the breach again.*" },
        SHIELD_WALL = { "This wall is older than your family tree and stands better!", "*rattles a knuckle against the dented shield rim; locks the shield close and braces into the allied line.*", "We'll talk about it over a pint later. Perhaps. Anyone going through me will need patience.", "*spits decisively into gloved hands; closes the final gap between shield and armour.*" },
        RETALIATION = { "By my grandmother's beard, now that's honest work! If you strike, you should enjoy the echo.", "*spits decisively into gloved hands; leaves a narrow gap in the guard and answers each attack with steel.*", "An anvil never complains when you strike it properly. Come on then. I have a moment for each of you.", "*pulls the helm low over bushy brows; plants the feet and waits for the first impatient blows.*" },
        MOCKING_BLOW = { "By my grandmother's beard, now that's honest work! Are you dangerous or merely loud?", "*pulls the helm low over bushy brows; lets the weapon point hang too low and invites the foe closer.*", "Shaking knees? Not in this family. Sorry. Mistook you for a training dummy.", "*plants the boots as though bracing against a mountain slope; makes a cheeky swing and grins over the shield.*" },
        BERSERKER_RAGE = { "By the anvil! Who drank my last ale?", "*plants the boots as though bracing against a mountain slope; rolls the shoulders as if shaking off an invisible weight.*", "The stone remembers everyone who gave way before it. Fear can wait outside. Fury's coming in.", "*sweeps a stray strand of beard out of the way; blows out a hard breath and holds an unbroken stare.*" },
        BLOODRAGE = { "My temper runs deep, right about ale-cask height. Pain is a message. I'll answer later.", "*sweeps a stray strand of beard out of the way; strikes a fist against the chest and gathers fighting spirit.*", "We'll talk about it over a pint later. Perhaps. My heart's still beating. That's enough explanation.", "*strikes the weapon pommel against the breastplate; grits the teeth and tightens the shoulders beneath the armour.*" },
        DISARM = { "Pretty sword. My smith would still have fixed it.", "*strikes the weapon pommel against the breastplate; tries to turn the enemy blade free with a short twist.*", "An anvil never complains when you strike it properly. Let's see if you're as talkative without a weapon.", "*rattles a knuckle against the dented shield rim; tries to catch the weapon's grip and twist it out of line.*" },
        INTIMIDATING_SHOUT = { "Anyone who can't hear that in the tavern is beyond help! Run while you still remember the way!", "*rattles a knuckle against the dented shield rim; throws a savage roar over the heads of the enemy.*", "Shaking knees? Not in this family. That was the friendly warning. The next comes with steel.", "*spits decisively into gloved hands; crashes the hilt against the shield and bares the teeth.*" },
        CHALLENGING_SHOUT = { "Anyone who can't hear that in the tavern is beyond help! ALL OF YOU, TO ME! I've room for every grudge!", "*spits decisively into gloved hands; throws both arms wide and challenges the entire enemy line.*", "The stone remembers everyone who gave way before it. Leave the others! I'm your problem today!", "*pulls the helm low over bushy brows; hammers the shield and bellows at the approaching foes.*" },
        SLAM = { "By my grandmother's beard, now that's honest work! It's not a hammer. Won't feel much different, though.", "*pulls the helm low over bushy brows; raises the weapon overhead and drops it with full weight.*", "We'll talk about it over a pint later. Perhaps. One clean hit beats five half-hearted ones.", "*plants the boots as though bracing against a mountain slope; pauses for a heartbeat and lets the weapon crash down.*" },
        DEVASTATE = { "By my grandmother's beard, now that's honest work! Already loose? Let's finish the job.", "*plants the boots as though bracing against a mountain slope; strikes an already weakened patch of armour.*", "An anvil never complains when you strike it properly. Looks like your smith saved money in the wrong place.", "*sweeps a stray strand of beard out of the way; taps the exposed seam, then strikes again.*" },
        SHIELD_SLAM = { "By my grandmother's beard, now that's honest work! Shields can close doors. Usually at face level.", "*sweeps a stray strand of beard out of the way; rips the shield from its guard and thrusts the rim forward.*", "Shaking knees? Not in this family. Whoever said defence was polite?", "*strikes the weapon pommel against the breastplate; lunges one step and lets the shield do the talking.*" },
        CONCUSSION_BLOW = { "By my grandmother's beard, now that's honest work! I'll try to throw you off your stride.", "*strikes the weapon pommel against the breastplate; tries to land a heavy blow in the gap between two movements.*", "The stone remembers everyone who gave way before it. I'll try to give everyone a moment of silence.", "*rattles a knuckle against the dented shield rim; shortens the grip and swings with startling force.*" },
        VICTORY_RUSH = { "These boots know only one direction: forward. One down. The others are still standing.", "*rattles a knuckle against the dented shield rim; uses the sudden breath of victory to surge forward.*", "We'll talk about it over a pint later. Perhaps. We can celebrate later. Something's still moving.", "*spits decisively into gloved hands; taps the chest once and presses on.*" },
        BATTLE_STANCE = { "My grandfather called that sound mountain sense. Two feet of good sense separate courage from stupidity.", "*spits decisively into gloved hands; plants both feet shoulder-width apart and rolls the blade loosely.*", "An anvil never complains when you strike it properly. I'll stay ready. The rest can make up its mind.", "*pulls the helm low over bushy brows; balances the weight between shield arm and sword hand.*" },
        DEFENSIVE_STANCE = { "A mountain does not ask how strong the storm is. If they want my friends, they must convince my shield.", "*pulls the helm low over bushy brows; widens the stance and lifts the shield before the allies.*", "Shaking knees? Not in this family. The loudest roar won't win this one.", "*plants the boots as though bracing against a mountain slope; drops the centre of gravity and becomes a wall behind the guard.*" },
        BERSERKER_STANCE = { "My temper runs deep, right about ale-cask height. Whoever said anger makes you blind has never looked properly.", "*plants the boots as though bracing against a mountain slope; draws deep breath and assumes a fierce, forward stance.*", "The stone remembers everyone who gave way before it. The world has become very simple: forward.", "*sweeps a stray strand of beard out of the way; loosens the shoulders, lowers the weapon, then snaps it up.*" },
        PIERCING_HOWL = { "Anyone who can't hear that in the tavern is beyond help! If you hear me, you're already too close.", "*sweeps a stray strand of beard out of the way; lets loose a howl that cuts through the surrounding clamour.*", "We'll talk about it over a pint later. Perhaps. No, that wasn't a pack of wolves. Just me.", "*strikes the weapon pommel against the breastplate; throws the head back and sustains a long, harsh cry.*" },
        SPEARING_STRIKE = { "By my grandmother's beard, now that's honest work! The opening is narrow. My point isn't.", "*strikes the weapon pommel against the breastplate; steps directly forward with the weapon extended.*", "An anvil never complains when you strike it properly. Armour is strong. Angles are stronger.", "*rattles a knuckle against the dented shield rim; turns the wrist toward a weak spot and drives the point home.*" },
        TACTICAL_MASTERY = { "My grandfather called that sound mountain sense. The difference between courage and foolishness is good footwork.", "*rattles a knuckle against the dented shield rim; shifts position barely an inch and keeps the battlefield in view.*", "Shaking knees? Not in this family. A battlefield isn't a dice game. You learn to read it.", "*spits decisively into gloved hands; studies every path, foe and retreat without lowering the weapon.*" },
