        BERSERKER_RAGE = { "The wilds know anger, and the limits it must keep. Fear? It has no room in my head today.", "*tilts the head as if listening to a distant forest; rolls the shoulders as if shaking off an invisible weight.*", "Some battles end only when the silence returns. Fear can wait outside. Fury's coming in.", "*glides quietly one step sideways; blows out a hard breath and holds an unbroken stare.*" },
        BLOODRAGE = { "The wilds know anger, and the limits it must keep. Pain is a message. I'll answer later.", "*glides quietly one step sideways; strikes a fist against the chest and gathers fighting spirit.*", "The night has a longer memory than this quarrel. My heart's still beating. That's enough explanation.", "*angles the blade after a fleeting glance at the sky; grits the teeth and tightens the shoulders beneath the armour.*" },
        DISARM = { "Even in battle there is a pause between falling leaves. Beautiful sword. May I see it a moment?", "*angles the blade after a fleeting glance at the sky; tries to turn the enemy blade free with a short twist.*", "I fight for the balance, never against it. Let's see if you're as talkative without a weapon.", "*touches an old leaf-shaped engraving with two fingers; tries to catch the weapon's grip and twist it out of line.*" },
        INTIMIDATING_SHOUT = { "My call carries through the darkness of the forest. Run while you still remember the way!", "*touches an old leaf-shaped engraving with two fingers; throws a savage roar over the heads of the enemy.*", "Even a falling tree chooses its path. That was the friendly warning. The next comes with steel.", "*lets the breath escape without a sound; crashes the hilt against the shield and bares the teeth.*" },
        CHALLENGING_SHOUT = { "My call carries through the darkness of the forest. ALL OF YOU, TO ME! I've room for every grudge!", "*lets the breath escape without a sound; throws both arms wide and challenges the entire enemy line.*", "Some battles end only when the silence returns. Leave the others! I'm your problem today!", "*adjusts the stance to the uneven ground; hammers the shield and bellows at the approaching foes.*" },
        SLAM = { "Even in battle there is a pause between falling leaves. It's not a hammer. Won't feel much different, though.", "*adjusts the stance to the uneven ground; raises the weapon overhead and drops it with full weight.*", "The night has a longer memory than this quarrel. One clean hit beats five half-hearted ones.", "*tilts the head as if listening to a distant forest; pauses for a heartbeat and lets the weapon crash down.*" },
        DEVASTATE = { "Even in battle there is a pause between falling leaves. Already loose? Let's finish the job.", "*tilts the head as if listening to a distant forest; strikes an already weakened patch of armour.*", "I fight for the balance, never against it. Looks like your smith saved money in the wrong place.", "*glides quietly one step sideways; taps the exposed seam, then strikes again.*" },
        SHIELD_SLAM = { "Even in battle there is a pause between falling leaves. Shields can close doors. Usually at face level.", "*glides quietly one step sideways; rips the shield from its guard and thrusts the rim forward.*", "Even a falling tree chooses its path. Whoever said defence was polite?", "*angles the blade after a fleeting glance at the sky; lunges one step and lets the shield do the talking.*" },
        CONCUSSION_BLOW = { "Even in battle there is a pause between falling leaves. I'll try to throw you off your stride.", "*angles the blade after a fleeting glance at the sky; tries to land a heavy blow in the gap between two movements.*", "Some battles end only when the silence returns. I'll try to give everyone a moment of silence.", "*touches an old leaf-shaped engraving with two fingers; shortens the grip and swings with startling force.*" },
        VICTORY_RUSH = { "The path appears when you listen to the wind. One down. The others are still standing.", "*touches an old leaf-shaped engraving with two fingers; uses the sudden breath of victory to surge forward.*", "The night has a longer memory than this quarrel. We can celebrate later. Something's still moving.", "*lets the breath escape without a sound; taps the chest once and presses on.*" },
        BATTLE_STANCE = { "Patience is the longest weapon I carry. Two feet of good sense separate courage from stupidity.", "*lets the breath escape without a sound; plants both feet shoulder-width apart and rolls the blade loosely.*", "I fight for the balance, never against it. I'll stay ready. The rest can make up its mind.", "*adjusts the stance to the uneven ground; balances the weight between shield arm and sword hand.*" },
        DEFENSIVE_STANCE = { "Ancient roots are not easily torn free. If they want my friends, they must convince my shield.", "*adjusts the stance to the uneven ground; widens the stance and lifts the shield before the allies.*", "Even a falling tree chooses its path. The loudest roar won't win this one.", "*tilts the head as if listening to a distant forest; drops the centre of gravity and becomes a wall behind the guard.*" },
        BERSERKER_STANCE = { "The wilds know anger, and the limits it must keep. Whoever said anger makes you blind has never looked properly.", "*tilts the head as if listening to a distant forest; draws deep breath and assumes a fierce, forward stance.*", "Some battles end only when the silence returns. The world has become very simple: forward.", "*glides quietly one step sideways; loosens the shoulders, lowers the weapon, then snaps it up.*" },
        PIERCING_HOWL = { "Listen to the night. This time it borrows my voice.", "*glides quietly one step sideways; lets loose a howl that cuts through the surrounding clamour.*", "The night has a longer memory than this quarrel. No, that wasn't a pack of wolves. Just me.", "*angles the blade after a fleeting glance at the sky; throws the head back and sustains a long, harsh cry.*" },
        SPEARING_STRIKE = { "Even in battle there is a pause between falling leaves. The opening is narrow. My point isn't.", "*angles the blade after a fleeting glance at the sky; steps directly forward with the weapon extended.*", "I fight for the balance, never against it. Armour is strong. Angles are stronger.", "*touches an old leaf-shaped engraving with two fingers; turns the wrist toward a weak spot and drives the point home.*" },
        TACTICAL_MASTERY = { "Sometimes the tree that bends first wins.", "*touches an old leaf-shaped engraving with two fingers; shifts position barely an inch and keeps the battlefield in view.*", "Even a falling tree chooses its path. A battlefield isn't a dice game. You learn to read it.", "*lets the breath escape without a sound; studies every path, foe and retreat without lowering the weapon.*" },
    },
    DRAENEI = {
        HEROIC_STRIKE = { "Let this be protection for my people, not triumph over the weak. Know why this blade is heavy? It rarely argues back.", "*touches a small keepsake on the armour; shifts weight onto the leading foot and brings the weapon down hard.*", "For every life behind me, I stand one heartbeat longer. Some arguments don't need a second sentence.", "*lowers the horns and distributes the weight evenly; drives the shoulder forward and lets the steel finish the point.*" },
        CHARGE = { "Every step is a promise to those left behind. If the road is blocked, I take the direct route.", "*lowers the horns and distributes the weight evenly; lowers a shoulder and launches forward in a cloud of dust.*", "The Light gives direction. I must still act. Coming through! That's a direction, not a warning!", "*sets the shield before the allies; bursts through an opening with a tremendous clatter.*" },
        REND = { "Let this be protection for my people, not triumph over the weak. Armour seams are tiny secrets. I'm curious.", "*sets the shield before the allies; draws the blade across an exposed gap in the guard.*", "Memories of lost worlds weigh upon my resolve. A tailor would be horrified. I'm quite pleased.", "*breathes deeply and settles into calm focus; draws the blade back and searches for another opening.*" },
        HAMSTRING = { "Let this be protection for my people, not triumph over the weak. Running away? That's a plan with serious flaws.", "*breathes deeply and settles into calm focus; ducks low beneath the enemy's guard.*", "I seek no glory, only a safe path home. I dislike chasing twice. Once is plenty.", "*checks the hooves' footing on the ground; sweeps low with the weapon and rises into guard again.*" },
        THUNDER_CLAP = { "Let this be protection for my people, not triumph over the weak. When the ground shakes, who needs a drummer?", "*checks the hooves' footing on the ground; stamps so hard that dust leaps from the earth.*", "For every life behind me, I stand one heartbeat longer. Hear that? Even the earth has objections.", "*lays a hand on an old family emblem; throws both arms wide as a dull boom rolls through the line.*" },
        CLEAVE = { "A clear mind withstands the fiercest storm. If you stand shoulder to shoulder, you can share the trouble.", "*lays a hand on an old family emblem; sends the weapon sweeping across a crowded arc.*", "The Light gives direction. I must still act. I hope you left enough room. I didn't.", "*touches a small keepsake on the armour; pivots on one heel and carries the momentum into the next arc.*" },
        EXECUTE = { "Let this be protection for my people, not triumph over the weak. I gave you every chance to withdraw.", "*touches a small keepsake on the armour; waits for a heartbeat, then brings down a final-looking blow.*", "Memories of lost worlds weigh upon my resolve. Negotiations are over.", "*lowers the horns and distributes the weight evenly; tightens the grip and closes the last opening.*" },
        SUNDER_ARMOR = { "Let this be protection for my people, not triumph over the weak. Lovely breastplate. Shame about the rivets.", "*lowers the horns and distributes the weight evenly; sets the blade against a loose edge of armour.*", "I seek no glory, only a safe path home. Expensive steel isn't the same as good protection.", "*sets the shield before the allies; traces a hard line along a gap between metal plates.*" },
        SHIELD_BLOCK = { "Steadfastness begins where others seek shelter. You'll have to knock first. This door stays closed.", "*sets the shield before the allies; turns the shield's rim to catch an incoming strike.*", "For every life behind me, I stand one heartbeat longer. A good shield listens before it answers.", "*breathes deeply and settles into calm focus; plants both boots and refuses to give an inch.*" },
        SHIELD_BASH = { "Let this be protection for my people, not triumph over the weak. Hush. Let's see if I can interrupt your spell.", "*breathes deeply and settles into calm focus; drives the shield forward between two syllables.*", "The Light gives direction. I must still act. My answer to magic comes with a wooden handle.", "*checks the hooves' footing on the ground; steps close and snaps the shield out without warning.*" },
        TAUNT = { "The vulnerable are not a target. Try me instead.", "*checks the hooves' footing on the ground; rattles the sword hilt against the shield three times.*", "Memories of lost worlds weigh upon my resolve. The others are busy. I'm not.", "*lays a hand on an old family emblem; steps out from the line and beckons the enemies closer.*" },
        BATTLE_SHOUT = { "You are not alone. Not a single one of you!", "*lays a hand on an old family emblem; beats the weapon hilt against the shield in rhythm.*", "I seek no glory, only a safe path home. You've legs to stand on and hearts to endure. Use both!", "*touches a small keepsake on the armour; rises before the allies and lifts the blade high.*" },
        DEMORALIZING_SHOUT = { "May my voice carry hope, not merely fear. The first of you are shaking. The rest will notice soon!", "*touches a small keepsake on the armour; unleashes a rough, deep cry from the chest.*", "For every life behind me, I stand one heartbeat longer. Look around. Who are you still fighting for?", "*lowers the horns and distributes the weight evenly; points the blade at the wavering enemy line.*" },
        REVENGE = { "Let this be protection for my people, not triumph over the weak. Thanks for the opportunity. It's coming right back.", "*lowers the horns and distributes the weight evenly; turns a weapon aside and strikes into the opening.*", "The Light gives direction. I must still act. I forget faces. Never blows.", "*sets the shield before the allies; rolls straight from defence into a counterattack.*" },
        OVERPOWER = { "Let this be protection for my people, not triumph over the weak. There's a gap. How generous of you.", "*sets the shield before the allies; slips past the missed strike and takes the open angle.*", "Memories of lost worlds weigh upon my resolve. Miss me once, invite me in.", "*breathes deeply and settles into calm focus; turns an enemy misstep into a swift counter.*" },
        MORTAL_STRIKE = { "Let this be protection for my people, not triumph over the weak. I'm not saving anything for a second try.", "*breathes deeply and settles into calm focus; sets both hands on the weapon and throws the body behind one strike.*", "I seek no glory, only a safe path home. Some duels end with words. Not this one.", "*checks the hooves' footing on the ground; steps forward and guides the steel with merciless precision.*" },
        WHIRLWIND = { "A clear mind withstands the fiercest storm. Go on, stand in a circle. Makes things easier.", "*checks the hooves' footing on the ground; spins through the press of bodies with the weapon extended.*", "For every life behind me, I stand one heartbeat longer. I like sharing. Today it's steel.", "*lays a hand on an old family emblem; sends the blade singing around in a wide sweep.*" },
        BLOODTHIRST = { "Even now, rage must never master my will. The pulse is racing. The hand stays steady.", "*lays a hand on an old family emblem; draws a sharp breath and presses the attack without mercy.*", "The Light gives direction. I must still act. Anger doesn't mean I'm inaccurate.", "*touches a small keepsake on the armour; surges forward with wild eyes and a measured grip.*" },
        INTERCEPT = { "Every step is a promise to those left behind. A head start is borrowed time.", "*touches a small keepsake on the armour; bursts from the melee and cuts off the escape.*", "Memories of lost worlds weigh upon my resolve. You're running? Excellent. I needed the exercise.", "*lowers the horns and distributes the weight evenly; springs off the ground and lands across the fleeing path.*" },
        PUMMEL = { "Let this be protection for my people, not triumph over the weak. Too many words. Not enough guard.", "*lowers the horns and distributes the weight evenly; disrupts the casting motion with a sharp, precise strike.*", "I seek no glory, only a safe path home. Were you saying something? No? Good.", "*sets the shield before the allies; knocks an arm out of rhythm with a compact blow.*" },
        SWEEPING_STRIKES = { "A clear mind withstands the fiercest storm. Why do half the job when there's a whole battle?", "*sets the shield before the allies; carries one swing smoothly into a second arc.*", "For every life behind me, I stand one heartbeat longer. More enemies? Fewer trips.", "*breathes deeply and settles into calm focus; keeps the blade moving through the crush instead of withdrawing it.*" },
        DEATH_WISH = { "Even now, rage must never master my will. Reason made its case. I disagreed.", "*breathes deeply and settles into calm focus; loosens the grip for a moment, then commits to the attack.*", "The Light gives direction. I must still act. I know the risk. Not sure they do.", "*checks the hooves' footing on the ground; glances once at the lowered guard before lunging forward.*" },
        RECKLESSNESS = { "Even now, rage must never master my will. Caution was yesterday. Today we act.", "*checks the hooves' footing on the ground; casts hesitation aside without loosening the weapon grip.*", "Memories of lost worlds weigh upon my resolve. You can lecture me tomorrow. If we have one.", "*lays a hand on an old family emblem; throws the whole body into a furious chain of strikes.*" },
        LAST_STAND = { "I have watched worlds fall. This position will hold.", "*lays a hand on an old family emblem; hauls upright once more and lifts the shield.*", "I seek no glory, only a safe path home. Still standing. That should answer you.", "*touches a small keepsake on the armour; sets shaking legs into the breach again.*" },
        SHIELD_WALL = { "No refugee behind me shall have to flee again today.", "*touches a small keepsake on the armour; locks the shield close and braces into the allied line.*", "For every life behind me, I stand one heartbeat longer. Anyone going through me will need patience.", "*lowers the horns and distributes the weight evenly; closes the final gap between shield and armour.*" },
        RETALIATION = { "Let this be protection for my people, not triumph over the weak. If you strike, you should enjoy the echo.", "*lowers the horns and distributes the weight evenly; leaves a narrow gap in the guard and answers each attack with steel.*", "The Light gives direction. I must still act. Come on then. I have a moment for each of you.", "*sets the shield before the allies; plants the feet and waits for the first impatient blows.*" },
        MOCKING_BLOW = { "Let this be protection for my people, not triumph over the weak. Are you dangerous or merely loud?", "*sets the shield before the allies; lets the weapon point hang too low and invites the foe closer.*", "Memories of lost worlds weigh upon my resolve. Sorry. Mistook you for a training dummy.", "*breathes deeply and settles into calm focus; makes a cheeky swing and grins over the shield.*" },
        BERSERKER_RAGE = { "Even now, rage must never master my will. Fear? It has no room in my head today.", "*breathes deeply and settles into calm focus; rolls the shoulders as if shaking off an invisible weight.*", "I seek no glory, only a safe path home. Fear can wait outside. Fury's coming in.", "*checks the hooves' footing on the ground; blows out a hard breath and holds an unbroken stare.*" },
