        DISARM = { "Let this be protection for my people, not triumph over the weak. Beautiful sword. May I see it a moment?", "*lays a hand on an old family emblem; tries to turn the enemy blade free with a short twist.*", "The Light gives direction. I must still act. Let's see if you're as talkative without a weapon.", "*touches a small keepsake on the armour; tries to catch the weapon's grip and twist it out of line.*" },
        INTIMIDATING_SHOUT = { "May my voice carry hope, not merely fear. Run while you still remember the way!", "*touches a small keepsake on the armour; throws a savage roar over the heads of the enemy.*", "Memories of lost worlds weigh upon my resolve. That was the friendly warning. The next comes with steel.", "*lowers the horns and distributes the weight evenly; crashes the hilt against the shield and bares the teeth.*" },
        CHALLENGING_SHOUT = { "May my voice carry hope, not merely fear. ALL OF YOU, TO ME! I've room for every grudge!", "*lowers the horns and distributes the weight evenly; throws both arms wide and challenges the entire enemy line.*", "I seek no glory, only a safe path home. Leave the others! I'm your problem today!", "*sets the shield before the allies; hammers the shield and bellows at the approaching foes.*" },
