        VICTORY_RUSH = { "Every step is a promise to those left behind. One down. The others are still standing.", "*touches a small keepsake on the armour; uses the sudden breath of victory to surge forward.*", "For every life behind me, I stand one heartbeat longer. We can celebrate later. Something's still moving.", "*lowers the horns and distributes the weight evenly; taps the chest once and presses on.*" },
