    ORC = {
        HEROIC_STRIKE = { "Honour is earned in deeds, not speeches. Know why this blade is heavy? It rarely argues back.", "*strikes a fist against an old clan marking; shifts weight onto the leading foot and brings the weapon down hard.*", "I will not let others stand alone in front of me. Some arguments don't need a second sentence.", "*bares the tusks in a determined grin; drives the shoulder forward and lets the steel finish the point.*" },
        CHARGE = { "Let those who stand before me tell how a clan fights!", "*bares the tusks in a determined grin; lowers a shoulder and launches forward in a cloud of dust.*", "My axe knows the truth about boasting. Coming through! That's a direction, not a warning!", "*plants both feet firmly in the churned earth; bursts through an opening with a tremendous clatter.*" },
