        PUMMEL = { "Honour is earned in deeds, not speeches. Too many words. Not enough guard.", "*bares the tusks in a determined grin; disrupts the casting motion with a sharp, precise strike.*", "May the ancestors see who I am in the way I stand. Were you saying something? No? Good.", "*plants both feet firmly in the churned earth; knocks an arm out of rhythm with a compact blow.*" },
        SWEEPING_STRIKES = { "The ancestors praise no victory purchased with foolishness. Why do half the job when there's a whole battle?", "*plants both feet firmly in the churned earth; carries one swing smoothly into a second arc.*", "I will not let others stand alone in front of me. More enemies? Fewer trips.", "*runs a thumb over a notch in the weapon haft; keeps the blade moving through the crush instead of withdrawing it.*" },
        DEATH_WISH = { "My rage burns hot. My purpose stays clear. Reason made its case. I disagreed.", "*runs a thumb over a notch in the weapon haft; loosens the grip for a moment, then commits to the attack.*", "My axe knows the truth about boasting. I know the risk. Not sure they do.", "*releases a short, rough breath; glances once at the lowered guard before lunging forward.*" },
        RECKLESSNESS = { "My rage burns hot. My purpose stays clear. Caution was yesterday. Today we act.", "*releases a short, rough breath; casts hesitation aside without loosening the weapon grip.*", "A warrior without responsibility is only a loud fool. You can lecture me tomorrow. If we have one.", "*tightens the leather wrap around the weapon grip; throws the whole body into a furious chain of strikes.*" },
        LAST_STAND = { "A broken line is a broken duty. This far. Not one step further.", "*tightens the leather wrap around the weapon grip; hauls upright once more and lifts the shield.*", "May the ancestors see who I am in the way I stand. Still standing. That should answer you.", "*strikes a fist against an old clan marking; sets shaking legs into the breach again.*" },
        SHIELD_WALL = { "A broken line is a broken duty. Behind me! No private heroics!", "*strikes a fist against an old clan marking; locks the shield close and braces into the allied line.*", "I will not let others stand alone in front of me. Anyone going through me will need patience.", "*bares the tusks in a determined grin; closes the final gap between shield and armour.*" },
        RETALIATION = { "Honour is earned in deeds, not speeches. If you strike, you should enjoy the echo.", "*bares the tusks in a determined grin; leaves a narrow gap in the guard and answers each attack with steel.*", "My axe knows the truth about boasting. Come on then. I have a moment for each of you.", "*plants both feet firmly in the churned earth; plants the feet and waits for the first impatient blows.*" },
        MOCKING_BLOW = { "Honour is earned in deeds, not speeches. Are you dangerous or merely loud?", "*plants both feet firmly in the churned earth; lets the weapon point hang too low and invites the foe closer.*", "A warrior without responsibility is only a loud fool. Sorry. Mistook you for a training dummy.", "*runs a thumb over a notch in the weapon haft; makes a cheeky swing and grins over the shield.*" },
        BERSERKER_RAGE = { "My rage burns hot. My purpose stays clear. Fear? It has no room in my head today.", "*runs a thumb over a notch in the weapon haft; rolls the shoulders as if shaking off an invisible weight.*", "May the ancestors see who I am in the way I stand. Fear can wait outside. Fury's coming in.", "*releases a short, rough breath; blows out a hard breath and holds an unbroken stare.*" },
        BLOODRAGE = { "My rage burns hot. My purpose stays clear. Pain is a message. I'll answer later.", "*releases a short, rough breath; strikes a fist against the chest and gathers fighting spirit.*", "I will not let others stand alone in front of me. My heart's still beating. That's enough explanation.", "*tightens the leather wrap around the weapon grip; grits the teeth and tightens the shoulders beneath the armour.*" },
        DISARM = { "Honour is earned in deeds, not speeches. Beautiful sword. May I see it a moment?", "*tightens the leather wrap around the weapon grip; tries to turn the enemy blade free with a short twist.*", "My axe knows the truth about boasting. Let's see if you're as talkative without a weapon.", "*strikes a fist against an old clan marking; tries to catch the weapon's grip and twist it out of line.*" },
        INTIMIDATING_SHOUT = { "Let every warrior in the clan hear my voice! Run while you still remember the way!", "*strikes a fist against an old clan marking; throws a savage roar over the heads of the enemy.*", "A warrior without responsibility is only a loud fool. That was the friendly warning. The next comes with steel.", "*bares the tusks in a determined grin; crashes the hilt against the shield and bares the teeth.*" },
        CHALLENGING_SHOUT = { "Let every warrior in the clan hear my voice! ALL OF YOU, TO ME! I've room for every grudge!", "*bares the tusks in a determined grin; throws both arms wide and challenges the entire enemy line.*", "May the ancestors see who I am in the way I stand. Leave the others! I'm your problem today!", "*plants both feet firmly in the churned earth; hammers the shield and bellows at the approaching foes.*" },
        SLAM = { "Honour is earned in deeds, not speeches. It's not a hammer. Won't feel much different, though.", "*plants both feet firmly in the churned earth; raises the weapon overhead and drops it with full weight.*", "I will not let others stand alone in front of me. One clean hit beats five half-hearted ones.", "*runs a thumb over a notch in the weapon haft; pauses for a heartbeat and lets the weapon crash down.*" },
        DEVASTATE = { "Honour is earned in deeds, not speeches. Already loose? Let's finish the job.", "*runs a thumb over a notch in the weapon haft; strikes an already weakened patch of armour.*", "My axe knows the truth about boasting. Looks like your smith saved money in the wrong place.", "*releases a short, rough breath; taps the exposed seam, then strikes again.*" },
        SHIELD_SLAM = { "Honour is earned in deeds, not speeches. Shields can close doors. Usually at face level.", "*releases a short, rough breath; rips the shield from its guard and thrusts the rim forward.*", "A warrior without responsibility is only a loud fool. Whoever said defence was polite?", "*tightens the leather wrap around the weapon grip; lunges one step and lets the shield do the talking.*" },
        CONCUSSION_BLOW = { "Honour is earned in deeds, not speeches. I'll try to throw you off your stride.", "*tightens the leather wrap around the weapon grip; tries to land a heavy blow in the gap between two movements.*", "May the ancestors see who I am in the way I stand. I'll try to give everyone a moment of silence.", "*strikes a fist against an old clan marking; shortens the grip and swings with startling force.*" },
        VICTORY_RUSH = { "Courage doesn't wait for the second call. One down. The others are still standing.", "*strikes a fist against an old clan marking; uses the sudden breath of victory to surge forward.*", "I will not let others stand alone in front of me. We can celebrate later. Something's still moving.", "*bares the tusks in a determined grin; taps the chest once and presses on.*" },
        BATTLE_STANCE = { "The ancestors praise no victory purchased with foolishness. Two feet of good sense separate courage from stupidity.", "*bares the tusks in a determined grin; plants both feet shoulder-width apart and rolls the blade loosely.*", "My axe knows the truth about boasting. I'll stay ready. The rest can make up its mind.", "*plants both feet firmly in the churned earth; balances the weight between shield arm and sword hand.*" },
        DEFENSIVE_STANCE = { "A broken line is a broken duty. If they want my friends, they must convince my shield.", "*plants both feet firmly in the churned earth; widens the stance and lifts the shield before the allies.*", "A warrior without responsibility is only a loud fool. The loudest roar won't win this one.", "*runs a thumb over a notch in the weapon haft; drops the centre of gravity and becomes a wall behind the guard.*" },
        BERSERKER_STANCE = { "My rage burns hot. My purpose stays clear. Whoever said anger makes you blind has never looked properly.", "*runs a thumb over a notch in the weapon haft; draws deep breath and assumes a fierce, forward stance.*", "May the ancestors see who I am in the way I stand. The world has become very simple: forward.", "*releases a short, rough breath; loosens the shoulders, lowers the weapon, then snaps it up.*" },
        PIERCING_HOWL = { "Let every warrior in the clan hear my voice! If you hear me, you're already too close.", "*releases a short, rough breath; lets loose a howl that cuts through the surrounding clamour.*", "I will not let others stand alone in front of me. No, that wasn't a pack of wolves. Just me.", "*tightens the leather wrap around the weapon grip; throws the head back and sustains a long, harsh cry.*" },
        SPEARING_STRIKE = { "Honour is earned in deeds, not speeches. The opening is narrow. My point isn't.", "*tightens the leather wrap around the weapon grip; steps directly forward with the weapon extended.*", "My axe knows the truth about boasting. Armour is strong. Angles are stronger.", "*strikes a fist against an old clan marking; turns the wrist toward a weak spot and drives the point home.*" },
        TACTICAL_MASTERY = { "The ancestors praise no victory purchased with foolishness. The difference between courage and foolishness is good footwork.", "*strikes a fist against an old clan marking; shifts position barely an inch and keeps the battlefield in view.*", "A warrior without responsibility is only a loud fool. A battlefield isn't a dice game. You learn to read it.", "*bares the tusks in a determined grin; studies every path, foe and retreat without lowering the weapon.*" },
    },
    TROLL = {
        HEROIC_STRIKE = { "Hope the loa are watching, things are about to get lively. Know why this blade is heavy? It rarely argues back.", "*touches a small charm at the belt; shifts weight onto the leading foot and brings the weapon down hard.*", "That's another fine story for later, heh. Some arguments don't need a second sentence.", "*sways to an imagined drumbeat for a breath; drives the shoulder forward and lets the steel finish the point.*" },
        CHARGE = { "My feet know paths other people don't even see. If the road is blocked, I take the direct route.", "*sways to an imagined drumbeat for a breath; lowers a shoulder and launches forward in a cloud of dust.*", "When the loa grin, I grin right back. Coming through! That's a direction, not a warning!", "*runs a thumb across a carved ancestral mark; bursts through an opening with a tremendous clatter.*" },
        REND = { "Hope the loa are watching, things are about to get lively. Armour seams are tiny secrets. I'm curious.", "*runs a thumb across a carved ancestral mark; draws the blade across an exposed gap in the guard.*", "Some call it luck. I call it practice. A tailor would be horrified. I'm quite pleased.", "*grins crookedly and shifts weight forward; draws the blade back and searches for another opening.*" },
        HAMSTRING = { "Hope the loa are watching, things are about to get lively. Running away? That's a plan with serious flaws.", "*grins crookedly and shifts weight forward; ducks low beneath the enemy's guard.*", "The ancestors see everything, especially the funny mistakes. I dislike chasing twice. Once is plenty.", "*taps out a swift rhythm with two fingers; sweeps low with the weapon and rises into guard again.*" },
        THUNDER_CLAP = { "Hope the loa are watching, things are about to get lively. When the ground shakes, who needs a drummer?", "*taps out a swift rhythm with two fingers; stamps so hard that dust leaps from the earth.*", "That's another fine story for later, heh. Hear that? Even the earth has objections.", "*draws a little bone bead from beneath the armour; throws both arms wide as a dull boom rolls through the line.*" },
        CLEAVE = { "The old witch doctor would've laughed at that. If you stand shoulder to shoulder, you can share the trouble.", "*draws a little bone bead from beneath the armour; sends the weapon sweeping across a crowded arc.*", "When the loa grin, I grin right back. I hope you left enough room. I didn't.", "*touches a small charm at the belt; pivots on one heel and carries the momentum into the next arc.*" },
        EXECUTE = { "Hope the loa are watching, things are about to get lively. I gave you every chance to withdraw.", "*touches a small charm at the belt; waits for a heartbeat, then brings down a final-looking blow.*", "Some call it luck. I call it practice. Negotiations are over.", "*sways to an imagined drumbeat for a breath; tightens the grip and closes the last opening.*" },
        SUNDER_ARMOR = { "Hope the loa are watching, things are about to get lively. Lovely breastplate. Shame about the rivets.", "*sways to an imagined drumbeat for a breath; sets the blade against a loose edge of armour.*", "The ancestors see everything, especially the funny mistakes. Expensive steel isn't the same as good protection.", "*runs a thumb across a carved ancestral mark; traces a hard line along a gap between metal plates.*" },
        SHIELD_BLOCK = { "Even a troll knows when to stand firm. You'll have to knock first. This door stays closed.", "*runs a thumb across a carved ancestral mark; turns the shield's rim to catch an incoming strike.*", "That's another fine story for later, heh. A good shield listens before it answers.", "*grins crookedly and shifts weight forward; plants both boots and refuses to give an inch.*" },
        SHIELD_BASH = { "Hope the loa are watching, things are about to get lively. Hush. Let's see if I can interrupt your spell.", "*grins crookedly and shifts weight forward; drives the shield forward between two syllables.*", "When the loa grin, I grin right back. My answer to magic comes with a wooden handle.", "*taps out a swift rhythm with two fingers; steps close and snaps the shield out without warning.*" },
        TAUNT = { "Hope the loa are watching, things are about to get lively. Over here! The trouble has my name on it.", "*taps out a swift rhythm with two fingers; rattles the sword hilt against the shield three times.*", "Some call it luck. I call it practice. The others are busy. I'm not.", "*draws a little bone bead from beneath the armour; steps out from the line and beckons the enemies closer.*" },
        BATTLE_SHOUT = { "The ancestors are listening, so make it loud! Heads up, ranks closed! No one falls alone today!", "*draws a little bone bead from beneath the armour; beats the weapon hilt against the shield in rhythm.*", "The ancestors see everything, especially the funny mistakes. You've legs to stand on and hearts to endure. Use both!", "*touches a small charm at the belt; rises before the allies and lifts the blade high.*" },
        DEMORALIZING_SHOUT = { "The ancestors are listening, so make it loud! The first of you are shaking. The rest will notice soon!", "*touches a small charm at the belt; unleashes a rough, deep cry from the chest.*", "That's another fine story for later, heh. Look around. Who are you still fighting for?", "*sways to an imagined drumbeat for a breath; points the blade at the wavering enemy line.*" },
        REVENGE = { "Hope the loa are watching, things are about to get lively. Thanks for the opportunity. It's coming right back.", "*sways to an imagined drumbeat for a breath; turns a weapon aside and strikes into the opening.*", "When the loa grin, I grin right back. I forget faces. Never blows.", "*runs a thumb across a carved ancestral mark; rolls straight from defence into a counterattack.*" },
        OVERPOWER = { "Hope the loa are watching, things are about to get lively. There's a gap. How generous of you.", "*runs a thumb across a carved ancestral mark; slips past the missed strike and takes the open angle.*", "Some call it luck. I call it practice. Miss me once, invite me in.", "*grins crookedly and shifts weight forward; turns an enemy misstep into a swift counter.*" },
        MORTAL_STRIKE = { "Hope the loa are watching, things are about to get lively. I'm not saving anything for a second try.", "*grins crookedly and shifts weight forward; sets both hands on the weapon and throws the body behind one strike.*", "The ancestors see everything, especially the funny mistakes. Some duels end with words. Not this one.", "*taps out a swift rhythm with two fingers; steps forward and guides the steel with merciless precision.*" },
        WHIRLWIND = { "The old witch doctor would've laughed at that. Go on, stand in a circle. Makes things easier.", "*taps out a swift rhythm with two fingers; spins through the press of bodies with the weapon extended.*", "That's another fine story for later, heh. I like sharing. Today it's steel.", "*draws a little bone bead from beneath the armour; sends the blade singing around in a wide sweep.*" },
        BLOODTHIRST = { "The drum in my chest beats faster today. The pulse is racing. The hand stays steady.", "*draws a little bone bead from beneath the armour; draws a sharp breath and presses the attack without mercy.*", "When the loa grin, I grin right back. Anger doesn't mean I'm inaccurate.", "*touches a small charm at the belt; surges forward with wild eyes and a measured grip.*" },
        INTERCEPT = { "Don't run off, mon. I'm right behind you!", "*touches a small charm at the belt; bursts from the melee and cuts off the escape.*", "Some call it luck. I call it practice. You're running? Excellent. I needed the exercise.", "*sways to an imagined drumbeat for a breath; springs off the ground and lands across the fleeing path.*" },
        PUMMEL = { "Hope the loa are watching, things are about to get lively. Too many words. Not enough guard.", "*sways to an imagined drumbeat for a breath; disrupts the casting motion with a sharp, precise strike.*", "The ancestors see everything, especially the funny mistakes. Were you saying something? No? Good.", "*runs a thumb across a carved ancestral mark; knocks an arm out of rhythm with a compact blow.*" },
        SWEEPING_STRIKES = { "The old witch doctor would've laughed at that. Why do half the job when there's a whole battle?", "*runs a thumb across a carved ancestral mark; carries one swing smoothly into a second arc.*", "That's another fine story for later, heh. More enemies? Fewer trips.", "*grins crookedly and shifts weight forward; keeps the blade moving through the crush instead of withdrawing it.*" },
