        SHIELD_WALL = { "Even a troll knows when to stand firm. Behind me! No private heroics!", "*touches a small charm at the belt; locks the shield close and braces into the allied line.*", "That's another fine story for later, heh. Anyone going through me will need patience.", "*sways to an imagined drumbeat for a breath; closes the final gap between shield and armour.*" },
        RETALIATION = { "Hope the loa are watching, things are about to get lively. If you strike, you should enjoy the echo.", "*sways to an imagined drumbeat for a breath; leaves a narrow gap in the guard and answers each attack with steel.*", "When the loa grin, I grin right back. Come on then. I have a moment for each of you.", "*runs a thumb across a carved ancestral mark; plants the feet and waits for the first impatient blows.*" },
