    TAUREN = {
        HEROIC_STRIKE = { "Thunder comes without hatred. Let my strike be the same. Know why this blade is heavy? It rarely argues back.", "*lowers the horns with solemn calm; shifts weight onto the leading foot and brings the weapon down hard.*", "The Earth Mother knows my reasons. Some arguments don't need a second sentence.", "*plants both hooves firmly in the earth; drives the shoulder forward and lets the steel finish the point.*" },
        CHARGE = { "When the herd moves, no fence holds it. If the road is blocked, I take the direct route.", "*plants both hooves firmly in the earth; lowers a shoulder and launches forward in a cloud of dust.*", "Strength belongs to those who use it to shelter others. Coming through! That's a direction, not a warning!", "*touches a braided keepsake on the weapon haft; bursts through an opening with a tremendous clatter.*" },
        REND = { "Thunder comes without hatred. Let my strike be the same. Armour seams are tiny secrets. I'm curious.", "*touches a braided keepsake on the weapon haft; draws the blade across an exposed gap in the guard.*", "My breath stays calm. The ground beneath me does not. A tailor would be horrified. I'm quite pleased.", "*breathes slowly through the nostrils; draws the blade back and searches for another opening.*" },
        HAMSTRING = { "Thunder comes without hatred. Let my strike be the same. Running away? That's a plan with serious flaws.", "*breathes slowly through the nostrils; ducks low beneath the enemy's guard.*", "Those who know the plains know when to stand firm. I dislike chasing twice. Once is plenty.", "*bows the head briefly toward the ground; sweeps low with the weapon and rises into guard again.*" },
        THUNDER_CLAP = { "Thunder remembers every step over the plains.", "*bows the head briefly toward the ground; stamps so hard that dust leaps from the earth.*", "The Earth Mother knows my reasons. Hear that? Even the earth has objections.", "*straightens a band decorated with feathers; throws both arms wide as a dull boom rolls through the line.*" },
        CLEAVE = { "Haste is not the same as resolve. If you stand shoulder to shoulder, you can share the trouble.", "*straightens a band decorated with feathers; sends the weapon sweeping across a crowded arc.*", "Strength belongs to those who use it to shelter others. I hope you left enough room. I didn't.", "*lowers the horns with solemn calm; pivots on one heel and carries the momentum into the next arc.*" },
        EXECUTE = { "Thunder comes without hatred. Let my strike be the same. I gave you every chance to withdraw.", "*lowers the horns with solemn calm; waits for a heartbeat, then brings down a final-looking blow.*", "My breath stays calm. The ground beneath me does not. Negotiations are over.", "*plants both hooves firmly in the earth; tightens the grip and closes the last opening.*" },
        SUNDER_ARMOR = { "Thunder comes without hatred. Let my strike be the same. Lovely breastplate. Shame about the rivets.", "*plants both hooves firmly in the earth; sets the blade against a loose edge of armour.*", "Those who know the plains know when to stand firm. Expensive steel isn't the same as good protection.", "*touches a braided keepsake on the weapon haft; traces a hard line along a gap between metal plates.*" },
        SHIELD_BLOCK = { "A mountain does not yield to the first storm. You'll have to knock first. This door stays closed.", "*touches a braided keepsake on the weapon haft; turns the shield's rim to catch an incoming strike.*", "The Earth Mother knows my reasons. A good shield listens before it answers.", "*breathes slowly through the nostrils; plants both boots and refuses to give an inch.*" },
        SHIELD_BASH = { "Thunder comes without hatred. Let my strike be the same. Hush. Let's see if I can interrupt your spell.", "*breathes slowly through the nostrils; drives the shield forward between two syllables.*", "Strength belongs to those who use it to shelter others. My answer to magic comes with a wooden handle.", "*bows the head briefly toward the ground; steps close and snaps the shield out without warning.*" },
        TAUNT = { "Thunder comes without hatred. Let my strike be the same. Over here! The trouble has my name on it.", "*bows the head briefly toward the ground; rattles the sword hilt against the shield three times.*", "My breath stays calm. The ground beneath me does not. The others are busy. I'm not.", "*straightens a band decorated with feathers; steps out from the line and beckons the enemies closer.*" },
        BATTLE_SHOUT = { "May the wind carry our resolve across the plains. Heads up, ranks closed! No one falls alone today!", "*straightens a band decorated with feathers; beats the weapon hilt against the shield in rhythm.*", "Those who know the plains know when to stand firm. You've legs to stand on and hearts to endure. Use both!", "*lowers the horns with solemn calm; rises before the allies and lifts the blade high.*" },
        DEMORALIZING_SHOUT = { "May the wind carry our resolve across the plains. The first of you are shaking. The rest will notice soon!", "*lowers the horns with solemn calm; unleashes a rough, deep cry from the chest.*", "The Earth Mother knows my reasons. Look around. Who are you still fighting for?", "*plants both hooves firmly in the earth; points the blade at the wavering enemy line.*" },
        REVENGE = { "Thunder comes without hatred. Let my strike be the same. Thanks for the opportunity. It's coming right back.", "*plants both hooves firmly in the earth; turns a weapon aside and strikes into the opening.*", "Strength belongs to those who use it to shelter others. I forget faces. Never blows.", "*touches a braided keepsake on the weapon haft; rolls straight from defence into a counterattack.*" },
        OVERPOWER = { "Thunder comes without hatred. Let my strike be the same. There's a gap. How generous of you.", "*touches a braided keepsake on the weapon haft; slips past the missed strike and takes the open angle.*", "My breath stays calm. The ground beneath me does not. Miss me once, invite me in.", "*breathes slowly through the nostrils; turns an enemy misstep into a swift counter.*" },
        MORTAL_STRIKE = { "Thunder comes without hatred. Let my strike be the same. I'm not saving anything for a second try.", "*breathes slowly through the nostrils; sets both hands on the weapon and throws the body behind one strike.*", "Those who know the plains know when to stand firm. Some duels end with words. Not this one.", "*bows the head briefly toward the ground; steps forward and guides the steel with merciless precision.*" },
        WHIRLWIND = { "Haste is not the same as resolve. Go on, stand in a circle. Makes things easier.", "*bows the head briefly toward the ground; spins through the press of bodies with the weapon extended.*", "The Earth Mother knows my reasons. I like sharing. Today it's steel.", "*straightens a band decorated with feathers; sends the blade singing around in a wide sweep.*" },
        BLOODTHIRST = { "Even the prairie burns sometimes to grow anew. The pulse is racing. The hand stays steady.", "*straightens a band decorated with feathers; draws a sharp breath and presses the attack without mercy.*", "Strength belongs to those who use it to shelter others. Anger doesn't mean I'm inaccurate.", "*lowers the horns with solemn calm; surges forward with wild eyes and a measured grip.*" },
        INTERCEPT = { "When the herd moves, no fence holds it. A head start is borrowed time.", "*lowers the horns with solemn calm; bursts from the melee and cuts off the escape.*", "My breath stays calm. The ground beneath me does not. You're running? Excellent. I needed the exercise.", "*plants both hooves firmly in the earth; springs off the ground and lands across the fleeing path.*" },
        PUMMEL = { "Thunder comes without hatred. Let my strike be the same. Too many words. Not enough guard.", "*plants both hooves firmly in the earth; disrupts the casting motion with a sharp, precise strike.*", "Those who know the plains know when to stand firm. Were you saying something? No? Good.", "*touches a braided keepsake on the weapon haft; knocks an arm out of rhythm with a compact blow.*" },
        SWEEPING_STRIKES = { "Haste is not the same as resolve. Why do half the job when there's a whole battle?", "*touches a braided keepsake on the weapon haft; carries one swing smoothly into a second arc.*", "The Earth Mother knows my reasons. More enemies? Fewer trips.", "*breathes slowly through the nostrils; keeps the blade moving through the crush instead of withdrawing it.*" },
        DEATH_WISH = { "Even the prairie burns sometimes to grow anew. Reason made its case. I disagreed.", "*breathes slowly through the nostrils; loosens the grip for a moment, then commits to the attack.*", "Strength belongs to those who use it to shelter others. I know the risk. Not sure they do.", "*bows the head briefly toward the ground; glances once at the lowered guard before lunging forward.*" },
        RECKLESSNESS = { "Even the prairie burns sometimes to grow anew. Caution was yesterday. Today we act.", "*bows the head briefly toward the ground; casts hesitation aside without loosening the weapon grip.*", "My breath stays calm. The ground beneath me does not. You can lecture me tomorrow. If we have one.", "*straightens a band decorated with feathers; throws the whole body into a furious chain of strikes.*" },
        LAST_STAND = { "As long as the earth bears me, it bears my oath.", "*straightens a band decorated with feathers; hauls upright once more and lifts the shield.*", "Those who know the plains know when to stand firm. Still standing. That should answer you.", "*lowers the horns with solemn calm; sets shaking legs into the breach again.*" },
        SHIELD_WALL = { "Behind my shield the young may breathe another day.", "*lowers the horns with solemn calm; locks the shield close and braces into the allied line.*", "The Earth Mother knows my reasons. Anyone going through me will need patience.", "*plants both hooves firmly in the earth; closes the final gap between shield and armour.*" },
        RETALIATION = { "Thunder comes without hatred. Let my strike be the same. If you strike, you should enjoy the echo.", "*plants both hooves firmly in the earth; leaves a narrow gap in the guard and answers each attack with steel.*", "Strength belongs to those who use it to shelter others. Come on then. I have a moment for each of you.", "*touches a braided keepsake on the weapon haft; plants the feet and waits for the first impatient blows.*" },
        MOCKING_BLOW = { "Thunder comes without hatred. Let my strike be the same. Are you dangerous or merely loud?", "*touches a braided keepsake on the weapon haft; lets the weapon point hang too low and invites the foe closer.*", "My breath stays calm. The ground beneath me does not. Sorry. Mistook you for a training dummy.", "*breathes slowly through the nostrils; makes a cheeky swing and grins over the shield.*" },
        BERSERKER_RAGE = { "Even the prairie burns sometimes to grow anew. Fear? It has no room in my head today.", "*breathes slowly through the nostrils; rolls the shoulders as if shaking off an invisible weight.*", "Those who know the plains know when to stand firm. Fear can wait outside. Fury's coming in.", "*bows the head briefly toward the ground; blows out a hard breath and holds an unbroken stare.*" },
        BLOODRAGE = { "Even the prairie burns sometimes to grow anew. Pain is a message. I'll answer later.", "*bows the head briefly toward the ground; strikes a fist against the chest and gathers fighting spirit.*", "The Earth Mother knows my reasons. My heart's still beating. That's enough explanation.", "*straightens a band decorated with feathers; grits the teeth and tightens the shoulders beneath the armour.*" },
        DISARM = { "Thunder comes without hatred. Let my strike be the same. Beautiful sword. May I see it a moment?", "*straightens a band decorated with feathers; tries to turn the enemy blade free with a short twist.*", "Strength belongs to those who use it to shelter others. Let's see if you're as talkative without a weapon.", "*lowers the horns with solemn calm; tries to catch the weapon's grip and twist it out of line.*" },
        INTIMIDATING_SHOUT = { "May the wind carry our resolve across the plains. Run while you still remember the way!", "*lowers the horns with solemn calm; throws a savage roar over the heads of the enemy.*", "My breath stays calm. The ground beneath me does not. That was the friendly warning. The next comes with steel.", "*plants both hooves firmly in the earth; crashes the hilt against the shield and bares the teeth.*" },
        CHALLENGING_SHOUT = { "Come all. The plains have room, and so do I.", "*plants both hooves firmly in the earth; throws both arms wide and challenges the entire enemy line.*", "Those who know the plains know when to stand firm. Leave the others! I'm your problem today!", "*touches a braided keepsake on the weapon haft; hammers the shield and bellows at the approaching foes.*" },
        SLAM = { "Thunder comes without hatred. Let my strike be the same. It's not a hammer. Won't feel much different, though.", "*touches a braided keepsake on the weapon haft; raises the weapon overhead and drops it with full weight.*", "The Earth Mother knows my reasons. One clean hit beats five half-hearted ones.", "*breathes slowly through the nostrils; pauses for a heartbeat and lets the weapon crash down.*" },
        DEVASTATE = { "Thunder comes without hatred. Let my strike be the same. Already loose? Let's finish the job.", "*breathes slowly through the nostrils; strikes an already weakened patch of armour.*", "Strength belongs to those who use it to shelter others. Looks like your smith saved money in the wrong place.", "*bows the head briefly toward the ground; taps the exposed seam, then strikes again.*" },
        SHIELD_SLAM = { "Thunder comes without hatred. Let my strike be the same. Shields can close doors. Usually at face level.", "*bows the head briefly toward the ground; rips the shield from its guard and thrusts the rim forward.*", "My breath stays calm. The ground beneath me does not. Whoever said defence was polite?", "*straightens a band decorated with feathers; lunges one step and lets the shield do the talking.*" },
        CONCUSSION_BLOW = { "Thunder comes without hatred. Let my strike be the same. I'll try to throw you off your stride.", "*straightens a band decorated with feathers; tries to land a heavy blow in the gap between two movements.*", "Those who know the plains know when to stand firm. I'll try to give everyone a moment of silence.", "*lowers the horns with solemn calm; shortens the grip and swings with startling force.*" },
        VICTORY_RUSH = { "When the herd moves, no fence holds it. One down. The others are still standing.", "*lowers the horns with solemn calm; uses the sudden breath of victory to surge forward.*", "The Earth Mother knows my reasons. We can celebrate later. Something's still moving.", "*plants both hooves firmly in the earth; taps the chest once and presses on.*" },
        BATTLE_STANCE = { "Haste is not the same as resolve. Two feet of good sense separate courage from stupidity.", "*plants both hooves firmly in the earth; plants both feet shoulder-width apart and rolls the blade loosely.*", "Strength belongs to those who use it to shelter others. I'll stay ready. The rest can make up its mind.", "*touches a braided keepsake on the weapon haft; balances the weight between shield arm and sword hand.*" },
        DEFENSIVE_STANCE = { "A mountain does not yield to the first storm. If they want my friends, they must convince my shield.", "*touches a braided keepsake on the weapon haft; widens the stance and lifts the shield before the allies.*", "My breath stays calm. The ground beneath me does not. The loudest roar won't win this one.", "*breathes slowly through the nostrils; drops the centre of gravity and becomes a wall behind the guard.*" },
        BERSERKER_STANCE = { "Even the prairie burns sometimes to grow anew. Whoever said anger makes you blind has never looked properly.", "*breathes slowly through the nostrils; draws deep breath and assumes a fierce, forward stance.*", "Those who know the plains know when to stand firm. The world has become very simple: forward.", "*bows the head briefly toward the ground; loosens the shoulders, lowers the weapon, then snaps it up.*" },
        PIERCING_HOWL = { "May the wind carry our resolve across the plains. If you hear me, you're already too close.", "*bows the head briefly toward the ground; lets loose a howl that cuts through the surrounding clamour.*", "The Earth Mother knows my reasons. No, that wasn't a pack of wolves. Just me.", "*straightens a band decorated with feathers; throws the head back and sustains a long, harsh cry.*" },
        SPEARING_STRIKE = { "Thunder comes without hatred. Let my strike be the same. The opening is narrow. My point isn't.", "*straightens a band decorated with feathers; steps directly forward with the weapon extended.*", "Strength belongs to those who use it to shelter others. Armour is strong. Angles are stronger.", "*lowers the horns with solemn calm; turns the wrist toward a weak spot and drives the point home.*" },
        TACTICAL_MASTERY = { "Haste is not the same as resolve. The difference between courage and foolishness is good footwork.", "*lowers the horns with solemn calm; shifts position barely an inch and keeps the battlefield in view.*", "My breath stays calm. The ground beneath me does not. A battlefield isn't a dice game. You learn to read it.", "*plants both hooves firmly in the earth; studies every path, foe and retreat without lowering the weapon.*" },
    },
    UNDEAD = {
        HEROIC_STRIKE = { "I've had worse days. Dying was one of them. Know why this blade is heavy? It rarely argues back.", "*pulls a loose glove over bony fingers; shifts weight onto the leading foot and brings the weapon down hard.*", "People have counted me out. Repeatedly. Some arguments don't need a second sentence.", "*tilts the head until something cracks audibly; drives the shoulder forward and lets the steel finish the point.*" },
        CHARGE = { "Faster than my own decay. That'll do. If the road is blocked, I take the direct route.", "*tilts the head until something cracks audibly; lowers a shoulder and launches forward in a cloud of dust.*", "My last breath was not my last word. Coming through! That's a direction, not a warning!", "*straightens an old seam in the coat; bursts through an opening with a tremendous clatter.*" },
        REND = { "I've had worse days. Dying was one of them. Armour seams are tiny secrets. I'm curious.", "*straightens an old seam in the coat; draws the blade across an exposed gap in the guard.*", "Creaking joints are merely a polite warning. A tailor would be horrified. I'm quite pleased.", "*brushes dust from a rusty buckle; draws the blade back and searches for another opening.*" },
        HAMSTRING = { "I've had worse days. Dying was one of them. Running away? That's a plan with serious flaws.", "*brushes dust from a rusty buckle; ducks low beneath the enemy's guard.*", "I remember my mistakes. Some of them wear armour now. I dislike chasing twice. Once is plenty.", "*checks a brittle joint bandage; sweeps low with the weapon and rises into guard again.*" },
        THUNDER_CLAP = { "I've had worse days. Dying was one of them. When the ground shakes, who needs a drummer?", "*checks a brittle joint bandage; stamps so hard that dust leaps from the earth.*", "People have counted me out. Repeatedly. Hear that? Even the earth has objections.", "*lets out a short, dry laugh; throws both arms wide as a dull boom rolls through the line.*" },
        CLEAVE = { "Without a heartbeat, there's quite a lot of time to think. If you stand shoulder to shoulder, you can share the trouble.", "*lets out a short, dry laugh; sends the weapon sweeping across a crowded arc.*", "My last breath was not my last word. I hope you left enough room. I didn't.", "*pulls a loose glove over bony fingers; pivots on one heel and carries the momentum into the next arc.*" },
        EXECUTE = { "I've had worse days. Dying was one of them. I gave you every chance to withdraw.", "*pulls a loose glove over bony fingers; waits for a heartbeat, then brings down a final-looking blow.*", "Creaking joints are merely a polite warning. Negotiations are over.", "*tilts the head until something cracks audibly; tightens the grip and closes the last opening.*" },
        SUNDER_ARMOR = { "I've had worse days. Dying was one of them. Lovely breastplate. Shame about the rivets.", "*tilts the head until something cracks audibly; sets the blade against a loose edge of armour.*", "I remember my mistakes. Some of them wear armour now. Expensive steel isn't the same as good protection.", "*straightens an old seam in the coat; traces a hard line along a gap between metal plates.*" },
        SHIELD_BLOCK = { "It's hard to frighten someone who's already been buried. You'll have to knock first. This door stays closed.", "*straightens an old seam in the coat; turns the shield's rim to catch an incoming strike.*", "People have counted me out. Repeatedly. A good shield listens before it answers.", "*brushes dust from a rusty buckle; plants both boots and refuses to give an inch.*" },
        SHIELD_BASH = { "I've had worse days. Dying was one of them. Hush. Let's see if I can interrupt your spell.", "*brushes dust from a rusty buckle; drives the shield forward between two syllables.*", "My last breath was not my last word. My answer to magic comes with a wooden handle.", "*checks a brittle joint bandage; steps close and snaps the shield out without warning.*" },
        TAUNT = { "Want a nightmare? I've already climbed out of bed.", "*checks a brittle joint bandage; rattles the sword hilt against the shield three times.*", "Creaking joints are merely a polite warning. The others are busy. I'm not.", "*lets out a short, dry laugh; steps out from the line and beckons the enemies closer.*" },
        BATTLE_SHOUT = { "My voice sounds hollow. The threat doesn't. Heads up, ranks closed! No one falls alone today!", "*lets out a short, dry laugh; beats the weapon hilt against the shield in rhythm.*", "I remember my mistakes. Some of them wear armour now. You've legs to stand on and hearts to endure. Use both!", "*pulls a loose glove over bony fingers; rises before the allies and lifts the blade high.*" },
        DEMORALIZING_SHOUT = { "My voice sounds hollow. The threat doesn't. The first of you are shaking. The rest will notice soon!", "*pulls a loose glove over bony fingers; unleashes a rough, deep cry from the chest.*", "People have counted me out. Repeatedly. Look around. Who are you still fighting for?", "*tilts the head until something cracks audibly; points the blade at the wavering enemy line.*" },
        REVENGE = { "I've had worse days. Dying was one of them. Thanks for the opportunity. It's coming right back.", "*tilts the head until something cracks audibly; turns a weapon aside and strikes into the opening.*", "My last breath was not my last word. I forget faces. Never blows.", "*straightens an old seam in the coat; rolls straight from defence into a counterattack.*" },
        OVERPOWER = { "I've had worse days. Dying was one of them. There's a gap. How generous of you.", "*straightens an old seam in the coat; slips past the missed strike and takes the open angle.*", "Creaking joints are merely a polite warning. Miss me once, invite me in.", "*brushes dust from a rusty buckle; turns an enemy misstep into a swift counter.*" },
        MORTAL_STRIKE = { "I've had worse days. Dying was one of them. I'm not saving anything for a second try.", "*brushes dust from a rusty buckle; sets both hands on the weapon and throws the body behind one strike.*", "I remember my mistakes. Some of them wear armour now. Some duels end with words. Not this one.", "*checks a brittle joint bandage; steps forward and guides the steel with merciless precision.*" },
