    BLOODELF = {
        HEROIC_STRIKE = { "A clean strike is more elegant than any threat. Know why this blade is heavy? It rarely argues back.", "*smooths a wrinkle from the embroidered sleeve; shifts weight onto the leading foot and brings the weapon down hard.*", "A clumsy movement would embarrass me more than a scratch. Some arguments don't need a second sentence.", "*adjusts an exquisitely crafted handguard; drives the shoulder forward and lets the steel finish the point.*" },
        CHARGE = { "Style doesn't require being slow. If the road is blocked, I take the direct route.", "*adjusts an exquisitely crafted handguard; lowers a shoulder and launches forward in a cloud of dust.*", "My ancestors would criticise the posture, never the courage. Coming through! That's a direction, not a warning!", "*rotates the weapon pommel with practiced grace; bursts through an opening with a tremendous clatter.*" },
        REND = { "A clean strike is more elegant than any threat. Armour seams are tiny secrets. I'm curious.", "*rotates the weapon pommel with practiced grace; draws the blade across an exposed gap in the guard.*", "The blade needs no ornament, only the correct angle. A tailor would be horrified. I'm quite pleased.", "*raises the chin by a barely noticeable angle; draws the blade back and searches for another opening.*" },
